update public.article_cache set translation = '{"sentences": [{"text": "일본의 사무라이 구메노 헤이나이는 수많은 사람을 죽인 후 불교에 귀의하게 되었습니다.", "translation": "Kumeno Heinai, a samurai of Japan, killed many people and later came to embrace Buddhism.", "vocab": [{"ko": "사무라이", "en": "samurai"}, {"ko": "수많다", "en": "numerous; countless"}, {"ko": "귀의하다", "en": "to embrace (a religion); to convert to"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ 후", "exp": "''After doing''. 죽이다 → 죽인 후 (after killing).", "example_in_sentence": "죽인 후"}, {"type": "grammar", "label": "~게 되다", "exp": "Auxiliary construction expressing a resultant or realized state. Marks the completion of a change or becoming. From 되다 (become) as auxiliary.", "example_in_sentence": "귀의하게 되었습니다"}]}, {"text": "그는 자신이 저지른 살생에 대해 깊이 참회하기 위해 특별한 방법을 선택하였습니다.", "translation": "He chose a special method in order to repent deeply for the killing he had committed.", "vocab": [{"ko": "저지르다", "en": "to commit (a crime, mistake, etc.)"}, {"ko": "살생", "en": "killing; taking of life"}, {"ko": "참회하다", "en": "to repent; to feel remorse"}, {"ko": "선택하다", "en": "to choose; to select"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past verb modifier)", "exp": "Lets a past action describe a noun. 저지르다 → 저지른 살생 (the killing he committed).", "example_in_sentence": "저지른"}, {"type": "grammar", "label": "~기 위해", "exp": "Purpose connective clause. Expresses intention or purpose of an action. From ~기 (nominalizer) + 위해 (for the sake of).", "example_in_sentence": "참회하기 위해"}]}, {"text": "그가 선택한 방법은 자신의 모습을 본뜬 돌상을 만드는 것이었습니다.", "translation": "The method he chose was to make a stone statue modeled after his own appearance.", "vocab": [{"ko": "본뜨다", "en": "to model after; to pattern after; to mold"}, {"ko": "돌상", "en": "stone statue"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ (past verb modifier)", "exp": "Lets a past action describe a noun. 선택하다 → 선택한 방법 (the method he chose).", "example_in_sentence": "선택한"}, {"type": "grammar", "label": "~는 것", "exp": "Nominalizing construction. Converts verb phrases into noun form to serve as predicate complement. From ~는 (present attributive) + 것 (thing/act).", "example_in_sentence": "만드는 것"}]}, {"text": "그 돌상을 절 입구에 묻어 사람들이 그 위를 밟고 지나가도록 하였습니다.", "translation": "He buried the stone statue at the temple entrance so that people would step on it as they passed.", "vocab": [{"ko": "묻다", "en": "to bury; to embed"}, {"ko": "밟다", "en": "to step on; to tread on"}], "analysis": [{"type": "grammar", "label": "~도록 하다", "exp": "''Make it so that ~ / arrange for ~''. 지나가다 → 지나가도록 하였습니다 (made it so people would walk over it).", "example_in_sentence": "지나가도록 하였습니다"}, {"type": "grammar", "label": "~고", "exp": "Connective marking sequential or coordinated actions. Expresses ''and then'' or ''and'' between parallel actions.", "example_in_sentence": "밟고 지나가"}]}, {"text": "이렇게 함으로써 그는 살생의 죄를 속죄하려고 하였습니다.", "translation": "By doing this, he attempted to atone for the sin of killing.", "vocab": [{"ko": "속죄하다", "en": "to atone; to make amends"}], "analysis": [{"type": "expression", "label": "~(으)ㅁ으로써", "exp": "''By doing ~''. 하다 → 함으로써; 이렇게 함으로써 (by doing this).", "example_in_sentence": "이렇게 함으로써"}, {"type": "grammar", "label": "~(으)려고 하다", "exp": "''Try / intend to''. 속죄하다 → 속죄하려고 하였습니다 (tried to atone).", "example_in_sentence": "속죄하려고 하였습니다"}]}, {"text": "자신의 형상을 발 아래에 두는 것은 극도의 겸손과 참회를 나타내는 행위라고 할 수 있습니다.", "translation": "Placing an image of oneself under people''s feet can be called an act that expresses extreme humility and repentance.", "vocab": [{"ko": "형상", "en": "form; figure; image"}, {"ko": "극도", "en": "extreme; utmost"}, {"ko": "겸손", "en": "humility; modesty"}, {"ko": "나타내다", "en": "to express; to show; to indicate"}], "analysis": [{"type": "grammar", "label": "~는 것", "exp": "Nominalizing construction. Converts verb phrase into noun form serving as subject. From ~는 (present attributive) + 것 (thing/act).", "example_in_sentence": "두는 것"}, {"type": "grammar", "label": "~(이)라고 할 수 있다", "exp": "''Can be called / one could say it is ~''. 행위 → 행위라고 할 수 있습니다 (can be called an act).", "example_in_sentence": "행위라고 할 수 있습니다"}]}, {"text": "구메노 헤이나이의 이야기는 폭력적인 삶을 살았던 한 사무라이가 불교의 가르침을 받아들이면서 자신의 과거를 어떻게 마주했는지를 보여 줍니다.", "translation": "The story of Kumeno Heinai shows how a samurai who had lived a violent life faced his past as he accepted the teachings of Buddhism.", "vocab": [{"ko": "폭력적", "en": "violent; brutal"}, {"ko": "가르침", "en": "teaching; doctrine"}, {"ko": "받아들이다", "en": "to accept; to embrace"}, {"ko": "마주하다", "en": "to face; to confront; to encounter"}], "analysis": [{"type": "grammar", "label": "~았/었던", "exp": "Past modifier for something that happened earlier: ''who had ~''. 살다 → 살았던 사무라이 (a samurai who had lived).", "example_in_sentence": "살았던"}, {"type": "grammar", "label": "~(으)면서", "exp": "''While / as'' — two things happen together. 받아들이다 → 받아들이면서 (as he accepted).", "example_in_sentence": "받아들이면서"}, {"type": "grammar", "label": "~았/었는지", "exp": "Embeds a question inside a sentence: ''how / whether ~''. 마주하다 → 어떻게 마주했는지를 (how he faced, used as the object).", "example_in_sentence": "마주했는지를"}]}], "version": "s6"}', vocab = '[{"ko": "사무라이", "en": "samurai", "note": ""}, {"ko": "수많다", "en": "numerous; countless", "note": ""}, {"ko": "귀의하다", "en": "to embrace (a religion); to convert to", "note": ""}, {"ko": "저지르다", "en": "to commit (a crime, mistake, etc.)", "note": ""}, {"ko": "살생", "en": "killing; taking of life", "note": ""}, {"ko": "참회하다", "en": "to repent; to feel remorse", "note": ""}, {"ko": "선택하다", "en": "to choose; to select", "note": ""}, {"ko": "본뜨다", "en": "to model after; to pattern after; to mold", "note": ""}, {"ko": "돌상", "en": "stone statue", "note": ""}, {"ko": "묻다", "en": "to bury; to embed", "note": ""}, {"ko": "밟다", "en": "to step on; to tread on", "note": ""}, {"ko": "속죄하다", "en": "to atone; to make amends", "note": ""}, {"ko": "형상", "en": "form; figure; image", "note": ""}, {"ko": "극도", "en": "extreme; utmos