update public.article_cache set translation = '{"texts": ["In 1918, the Bolsheviks executed Russia''s last emperor Nicholas II and his family. Those executed were the emperor and his wife, five children, and four servants.", "At that time, there were also dogs at the imperial court. The Bolsheviks also executed the two dogs that were with them. However, one dog named Joie managed to survive.", "The reason Joie survived is said to be that the dog did not bark. Thanks to not barking, (the dog) was able to avoid execution.", "After that, Joie was rescued, went to Britain, and spent the rest of its life there. Among the members of Emperor Nicholas II''s imperial household, Joie was the only one who escaped execution and survived."], "sentences": [{"text": "1918년, 볼셰비키는 러시아의 마지막 황제 니콜라이 2세와 그의 가족을 처형했습니다.", "translation": "In 1918, the Bolsheviks executed Russia''s last emperor Nicholas II and his family.", "vocab": [{"ko": "볼셰비키", "en": "Bolshevik", "note": ""}, {"ko": "황제", "en": "emperor", "note": ""}, {"ko": "처형하다", "en": "to execute", "note": ""}, {"ko": "가족", "en": "family", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "Past tense formal-polite ending. 처형하다 → 처형했습니다.", "example_in_sentence": "처형했습니다"}, {"type": "grammar", "label": "~과/와 (with — comitative / and — listing)", "exp": "Listing connector joining two noun phrases. 니콜라이 2세 and his family are both objects of execution.", "example_in_sentence": "니콜라이 2세와 그의 가족"}]}, {"text": "처형된 이들은 황제 부부, 다섯 자녀, 그리고 네 명의 시종이었습니다.", "translation": "Those executed were the emperor and his wife, five children, and four servants.", "vocab": [{"ko": "황제", "en": "emperor", "note": ""}, {"ko": "부부", "en": "husband and wife; couple", "note": ""}, {"ko": "자녀", "en": "child; children", "note": ""}, {"ko": "시종", "en": "servant; attendant", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "Past tense formal-polite copula. 이다 → 이었습니다.", "example_in_sentence": "이었습니다"}]}, {"text": "당시 황실에는 개도 함께 있었습니다.", "translation": "At that time, there were also dogs at the imperial court.", "vocab": [{"ko": "황실", "en": "imperial court; imperial household", "note": ""}, {"ko": "개", "en": "dog", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "Past tense formal-polite. 있다 → 있었습니다.", "example_in_sentence": "있었습니다"}, {"type": "grammar", "label": "~도 (also / even)", "exp": "Additive particle. The dogs were also present (in addition to people).", "example_in_sentence": "개도"}]}, {"text": "볼셰비키는 함께 있던 개 두 마리도 처형했습니다.", "translation": "The Bolsheviks also executed the two dogs that were with them.", "vocab": [{"ko": "볼셰비키", "en": "Bolshevik", "note": ""}, {"ko": "마리", "en": "counter for animals", "note": ""}, {"ko": "처형하다", "en": "to execute", "note": ""}], "analysis": [{"type": "grammar", "label": "~던 (retrospective modifier)", "exp": "Past habitual/state modifier on a noun. The dogs that were (at that time) together.", "example_in_sentence": "함께 있던 개"}, {"type": "grammar", "label": "~도 (also / even)", "exp": "Additive particle. The dogs too were executed (in addition to people).", "example_in_sentence": "마리도"}, {"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "Past tense formal-polite. 처형하다 → 처형했습니다.", "example_in_sentence": "처형했습니다"}]}, {"text": "그러나 조이라는 이름의 개 한 마리는 살아남게 되었습니다.", "translation": "However, one dog named Joie managed to survive.", "vocab": [{"ko": "조이", "en": "Joie (dog name)", "note": ""}, {"ko": "이름", "en": "name", "note": ""}, {"ko": "살아남다", "en": "to survive", "note": ""}], "analysis": [{"type": "grammar", "label": "~(이)라는 N", "exp": "''Called / named ~'' before a noun. 조이 → 조이라는 이름의 개 (a dog named Joie).", "example_in_sentence": "조이라는 이름의 개"}, {"type": "grammar", "label": "~게 되다 (come to / passive)", "exp": "Expresses circumstance or outcome. Came to survive; ended up surviving.", "example_in_sentence": "살아남게 되었습니다"}]}, {"text": "조이가 살아남은 이유는 짖지 않았기 때문이라고 합니다.", "translation": "The reason Joie survived is said to be that the dog did not bark.", "vocab": [{"ko": "이유", "en": "reason", "note": ""}, {"ko": "짖다", "en": "to bark", "note": ""}], "analysis": [{"type": "grammar", "label": "~지 않다", "exp": "Negation. 짖다 → 짖지 않다 → 짖지 않았다 (did not bark).", "example_in_sentence": "짖지 않았기"}, {"type": "grammar", "label": "~기 때문이라고 하다", "exp": "Gives a reported reason: ''it is said to be because ~''. 않다 → 않았기 때문이라고 합니다 (reportedly because it did not).", "example_in_sentence": "않았기 때문이라고 합니다"}]}, {"text": "짖지 않은 덕분에 처형을 피할 수 있었던 것입니다.", "translation": "Thanks to not barking, (the dog) was able to avoid execution.", "vocab": [{"ko": "처형", "en": "execution", "note": ""}, {"ko": "피하다", "en": "to avoid; to escape", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ 덕분에", "exp": "''Thanks to ~ing'' — gives the reason for a good result. 않다 → 짖지 않은 덕분에 (thanks to not barking).", "example_in_sentence": "짖지 않은 덕분에"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다/없다 (ability/possibility)", "exp": "Ability/possibility marker. 피하다 → 피할 수 있다 → 피할 수 있었다 (was able to avoid).", "example_in_sentence": "피할 수 있었던"}, {"type": "grammar", "label": "~았/었던 것이다", "exp": "Explains what happened: ''it was that ~''. 있다 → 피할 수 있었던 것입니다 (that is how it was able to avoid it).", "example_in_sentence": "피할 수 있었던 것입니다"}]}, {"text": "이후 조이는 구조되었으며, 영국으로 건너가 그곳에서 여생을 보냈습니다.", "translation": "After that, Joie was rescued, went to Britain, and spent the rest of its life there.", "vocab": [{"ko": "구조되다", "en": "to be rescued", "note": ""}, {"ko": "영국", "en": "Britain; United Kingdom", "note": ""}, {"ko": "건너가다", "en": "to cross over; to go abroad", "note": ""}, {"ko": "여생", "en": "remaining life; rest of one''s life", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었으며", "exp": "Formal written ''and'' after a past verb. 구조되다 → 구조되었으며 (was rescued, and).", "example_in_sentence": "구조되었으며"}, {"type": "grammar", "label": "~(으)로 (means / direction / transformation)", "exp": "Direction/destination marker. Toward/to Britain.", "example_in_sentence": "영국으로"}, {"type": "grammar", "label": "~에서 (action-location / source / starting point)", "exp": "Location of action. Spent (the rest of life) in that place.", "example_in_sentence": "그곳에서"}, {"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "Past tense formal-polite. 보내다 → 보냈습니다.", "example_in_sentence": "보냈습니다"}]}, {"text": "니콜라이 2세 황실 구성원 중 처형을 피해 살아남은 것은 조이가 유일했습니다.", "translation": "Among the members of Emperor Nicholas II''s imperial household, Joie was the only one who escaped execution and survived.", "vocab": [{"ko": "황실", "en": "imperial court; imperial household", "note": ""}, {"ko": "구성원", "en": "member", "note": ""}, {"ko": "처형", "en": "execution", "note": ""}, {"ko": "피하다", "en": "to avoid; to escape", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "Past tense formal-polite copula. 유일하다 → 유일했습니다.", "example_in_sentence": "유일했습니다"}]}], "version": "s6"}', vocab = '[{"ko": "볼셰비키", "en": "Bolshevik", "note": ""}, {"ko": "황제", "en": "emperor", "note": ""}, {"ko": "처형하다", "en": "to execute", "note": ""}, {"ko": "가족", "en": "family", "note": ""}, {"ko": "부부", "en": "husband and wife; couple", "note": ""}, {"ko": "자녀", "en": "child; children", "note": ""}, {"ko": "시종", "en": "servant; attendant", "note": ""}, {"ko": "황실", "en": "imperial court; imperial household", "note": ""}, {"ko": "개", "en": "dog", "note": ""}, {"ko": "마리", "en": "counter for animals", "note": ""}, {"ko": "조이", "en": "Joie (dog name)", "note": ""}, {"ko": "이름", "en": "name", "note": ""}, {"ko": "살아남다", "en": "to survive", "note": ""}, {"ko": "이유", "en": "reason", "note": ""}, {"ko": "짖다", "en": "to bark", "note": ""}, {"ko": "처형", "en": "execution", "note": ""}, {"ko": "피하다", "en": "to avoid; to escape", "note": ""}, {"ko": "구조되다", "en": "to be rescued", "note": ""}, {"ko": "영국", "en": "Britain; United Kingdom", "note": ""}, {"ko": "건너가다", "en": "to cross over; to go abroad", "note": ""}, {"ko": "여생", "en": "remaining life; rest of one''s life", "note": ""}, {"ko": "구성원", "en": "member", "note": ""}]', grammar = '{"patterns": [{"name": "~았/었/였습니다 (past formal)", "level": "Intermediate", "exp": "Past tense formal-polite ending. 처형하다 → 처형했습니다.", "ex_ko": "1918년, 볼셰비키는 러시아의 마지막 황제 니콜라이 2세와 그의 가족을 처형했습니다.", "ex_en": "In 1918, the Bolsheviks executed Russia''s last emperor Nicholas II and his family."}, {"name": "~과/와 (with — comitative / and — listing)", "level": "Intermediate", "exp": "Listing connector joining two noun phrases. 니콜라이 2세 and his family are both objects of execution.", "ex_ko": "1918년, 볼셰비키는 러시아의 마지막 황제 니콜라이 2세와 그의 가족을 처형했습니다.", "ex_en": "In 1918, the Bolsheviks executed Russia''s last emperor Nicholas II and his family."}, {"name": "~도 (also / even)", "level": "Intermediate", "exp": "Additive particle. The dogs were also present (in addition to people).", "ex_ko": "당시 황실에는 개도 함께 있었습니다.", "ex_en": "At that time, there were also dogs at the imperial court."}, {"name": "~던 (retrospective modifier)", "level": "Intermediate", "exp": "Past habitual/state modifier on a noun. The dogs that were (at that time) together.", "ex_ko": "볼셰비키는 함께 있던 개 두 마리도 처형했습니다.", "ex_en": "The Bolsheviks also executed the two dogs that were with them."}, {"name": "~(이)라는 N", "level": "Intermediate", "exp": "''Called / named ~'' before a noun. 조이 → 조이라는 이름의 개 (a dog named Joie).", "ex_ko": "그러나 조이라는 이름의 개 한 마리는 살아남게 되었습니다.", "ex_en": "However, one dog named Joie managed to survive."}, {"name": "~게 되다 (come to / passive)", "level": "Intermediate", "exp": "Expresses circumstance or outcome. Came to survive; ended up surviving.", "ex_ko": "그러나 조이라는 이름의 개 한 마리는 살아남게 되었습니다.", "ex_en": "However, one dog named Joie managed to survive."}, {"name": "~지 않다", "level": "Intermediate", "exp": "Negation. 짖다 → 짖지 않다 → 짖지 않았다 (did not bark).", "ex_ko": "조이가 살아남은 이유는 짖지 않았기 때문이라고 합니다.", "ex_en": "The reason Joie survived is said to be that the dog did not bark."}, {"name": "~기 때문이라고 하다", "level": "Intermediate", "exp": "Gives a reported reason: ''it is said to be because ~''. 않다 → 않았기 때문이라고 합니다 (reportedly because it did not).", "ex_ko": "조이가 살아남은 이유는 짖지 않았기 때문이라고 합니다.", "ex_en": "The reason Joie survived is said to be that the dog did not bark."}, {"name": "~(으)ㄴ 덕분에", "level": "Intermediate", "exp": "''Thanks to ~ing'' — gives the reason for a good result. 않다 → 짖지 않은 덕분에 (thanks to not barking).", "ex_ko": "짖지 않은 덕분에 처형을 피할 수 있었던 것입니다.", "ex_en": "Thanks to not barking, (the dog) was able to avoid execution."}, {"name": "~(으)ㄹ 수 있다/없다 (ability/possibility)", "level": "Intermediate", "exp": "Ability/possibility marker. 피하다 → 피할 수 있다 → 피할 수 있었다 (was able to avoid).", "ex_ko": "짖지 않은 덕분에 처형을 피할 수 있었던 것입니다.", "ex_en": "Thanks to not barking, (the dog) was able to avoid execution."}, {"name": "~았/었던 것이다", "level": "Intermediate", "exp": "Explains what happened: ''it was that ~''. 있다 → 피할 수 있었던 것입니다 (that is how it was able to avoid it).", "ex_ko": "짖지 않은 덕분에 처형을 피할 수 있었던 것입니다.", "ex_en": "Thanks to not barking, (the dog) was able to avoid execution."}, {"name": "~았/었으며", "level": "Intermediate", "exp": "Formal written ''and'' after a past verb. 구조되다 → 구조되었으며 (was rescued, and).", "ex_ko": "이후 조이는 구조되었으며, 영국으로 건너가 그곳에서 여생을 보냈습니다.", "ex_en": "After that, Joie was rescued, went to Britain, and spent the rest of its life there."}, {"name": "~(으)로 (means / direction / transformation)", "level": "Intermediate", "exp": "Direction/destination marker. Toward/to Britain.", "ex_ko": "이후 조이는 구조되었으며, 영국으로 건너가 그곳에서 여생을 보냈습니다.", "ex_en": "After that, Joie was rescued, went to Britain, and spent the rest of its life there."}, {"name": "~에서 (action-location / source / starting point)", "level": "Intermediate", "exp": "Location of action. Spent (the rest of life) in that place.", "ex_ko": "이후 조이는 구조되었으며, 영국으로 건너가 그곳에서 여생을 보냈습니다.", "ex_en": "After that, Joie was rescued, went to Britain, and spent the rest of its life there."}]}', updated_at = now() where article_id = 'mpg4bp2fcj1w' and md5(translation) = '02596a8797af4b4b87be48d54d71c5ca';
update public.article_cache set translation = '{"texts": ["The technique in which an actor directly looks at the camera and speaks to the audience is called ''breaking the fourth wall.'' The work that first used this technique in a feature-length narrative film is known to be the 1918 silent film ''Men Who Have Made Love to Me.''", "The lead role in this film was actress Mary MacLane. While playing a fictional character modeled on her real self, she stepped outside the narrative scenes and spoke directly toward the camera.", "The character Mary MacLane played was not an entirely new character, but rather one based on herself. A case like this, in which a real person directly played themselves and even broke the fourth wall, was extremely unusual for the time.", "''Men Who Have Made Love to Me'' is a film made well over 100 years from now, yet it is recorded as a work through which the origins of the fourth-wall-breaking technique can be confirmed."], "sentences": [{"text": "영화에서 배우가 카메라를 직접 바라보며 관객에게 말을 거는 기법을 ''네 번째 벽 허물기''라고 합니다.", "translation": "The technique in which an actor directly looks at the camera and speaks to the audience is called ''breaking the fourth wall.''", "vocab": [{"ko": "바라보다", "en": "to look at, to gaze at", "note": "direct visual attention toward something"}, {"ko": "관객", "en": "audience, spectator", "note": "people watching a performance or film"}, {"ko": "기법", "en": "technique, method", "note": "specialized or artistic technique"}, {"ko": "허물다", "en": "to break down, to demolish", "note": "used figuratively here for ''breaking'' a barrier"}], "analysis": [{"type": "grammar", "label": "~(으)며", "exp": "Written connector meaning ''while / and''. 바라보다 → 바라보며 (while looking at).", "example_in_sentence": "바라보며"}, {"type": "grammar", "label": "~에서 (location/source)", "exp": "Marks the location where an action takes place. 영화 + 에서 = ''in (a/the) film.'' 학교에서 공부하다 (study at school).", "example_in_sentence": "영화에서"}, {"type": "grammar", "label": "~에게/한테 (to person)", "exp": "Indirect object marker for animate recipients. 관객 + 에게 = ''to the audience.'' 친구에게 편지를 쓰다 (write a letter to a friend).", "example_in_sentence": "관객에게"}]}, {"text": "이 기법을 장편 서사 영화 최초로 사용한 작품이 1918년 무성 영화 《나를 사랑한 남자들》이라고 알려져 있습니다.", "translation": "The work that first used this technique in a feature-length narrative film is known to be the 1918 silent film ''Men Who Have Made Love to Me.''", "vocab": [{"ko": "장편", "en": "feature-length, full-length", "note": "refers to long-form works, especially films or novels"}, {"ko": "무성 영화", "en": "silent film", "note": "film with no synchronized recorded dialogue"}, {"ko": "최초", "en": "the first, the earliest", "note": "Sino-Korean noun meaning ''for the first time / the very first''"}], "analysis": [{"type": "grammar", "label": "~(으)로 (as)", "exp": "최초 + 로 → 최초로 (for the first time / as the first).", "example_in_sentence": "최초로"}, {"type": "grammar", "label": "~(이)라고 알려져 있다", "exp": "''Is known to be ~''. 《나를 사랑한 남자들》이라고 알려져 있습니다 (is known to be the film ''Men Who Have Made Love to Me'').", "example_in_sentence": "《나를 사랑한 남자들》이라고 알려져 있습니다"}]}, {"text": "이 영화의 주연은 배우 메리 맥레인이었습니다.", "translation": "The lead role in this film was actress Mary MacLane.", "vocab": [{"ko": "주연", "en": "lead role, starring role", "note": "the main actor/actress in a film or play"}], "analysis": [{"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "Past tense formal-polite ending. 이다 → 이었습니다 = ''was.'' 학생이었습니다 (was a student).", "example_in_sentence": "메리 맥레인이었습니다"}]}, {"text": "그녀는 실제 자신을 모델로 한 허구의 인물을 연기하면서, 서사 장면 밖으로 나와 카메라를 향해 직접 말을 걸었습니다.", "translation": "While playing a fictional character modeled on her real self, she stepped outside the narrative scenes and spoke directly toward the camera.", "vocab": [{"ko": "허구", "en": "fiction, fabrication", "note": "something invented, not real"}, {"ko": "연기하다", "en": "to act, to perform", "note": "to portray a character in film or theater"}, {"ko": "서사", "en": "narrative, epic", "note": "the story or storytelling element of a work"}], "analysis": [{"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "Past tense formal-polite ending. 걸다 → 걸었습니다 = ''spoke (to).'' 먹다 → 먹었습니다 (ate).", "example_in_sentence": "말을 걸었습니다"}, {"type": "grammar", "label": "~(으)면서 (while)", "exp": "Simultaneous action ''while/as.'' 연기하다 → 연기하면서 = ''while acting.'' 먹다 → 먹으면서 (while eating).", "example_in_sentence": "연기하면서"}, {"type": "grammar", "label": "~을/를 N(으)로 한", "exp": "''Using ~ as N / modeled on ~'' before a noun. 자신을 모델로 한 인물 (a character modeled on herself).", "example_in_sentence": "자신을 모델로 한"}, {"type": "grammar", "label": "~아/어 (and then)", "exp": "Links actions in order: ''did ~ and then''. 나오다 → 나와 (came out and ...).", "example_in_sentence": "밖으로 나와"}, {"type": "grammar", "label": "~을/를 향해(서) / 향한 (toward / aimed at)", "exp": "Indicates direction or aim. 카메라 + 를 향해 = ''toward the camera.'' 미래를 향해 나아가다 (move toward the future).", "example_in_sentence": "카메라를 향해"}]}, {"text": "메리 맥레인이 연기한 인물은 완전히 새로운 캐릭터가 아니라, 자기 자신을 바탕으로 한 인물이었습니다.", "translation": "The character Mary MacLane played was not an entirely new character, but rather one based on herself.", "vocab": [{"ko": "바탕", "en": "basis, foundation", "note": "the underlying base or foundation something is built on"}, {"ko": "자기 자신", "en": "oneself, one''s own self", "note": "emphatic reflexive pronoun"}], "analysis": [{"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "Past tense formal-polite ending. 인물이다 → 인물이었습니다 = ''was a person/character.'' 선생님이었습니다 (was a teacher).", "example_in_sentence": "인물이었습니다"}, {"type": "grammar", "label": "~히 (adverb suffix, Sino-Korean)", "exp": "Adverbializer for Sino-Korean adjective stems. 완전하다 → 완전히 = ''completely.'' 정확하다 → 정확히 (accurately).", "example_in_sentence": "완전히"}, {"type": "grammar", "label": "~을/를 바탕으로 한", "exp": "''Based on ~'' before a noun. 자기 자신을 바탕으로 한 인물 (a character based on herself).", "example_in_sentence": "자기 자신을 바탕으로 한"}, {"type": "grammar", "label": "ㅂ 불규칙 (ㅂ irregular)", "exp": "새롭다 is ㅂ-irregular: ㅂ becomes 우 before a vowel ending. 새롭다 → 새로운 (new).", "example_in_sentence": "새로운"}]}, {"text": "이처럼 실존 인물이 자신을 직접 연기하면서 네 번째 벽까지 허문 사례는 당시로서는 매우 이례적인 것이었습니다.", "translation": "A case like this, in which a real person directly played themselves and even broke the fourth wall, was extremely unusual for the time.", "vocab": [{"ko": "실존", "en": "real existence, actual existence", "note": "Sino-Korean; refers to actually existing persons or things"}, {"ko": "사례", "en": "case, example, instance", "note": "a specific occurrence used as an example"}, {"ko": "이례적이다", "en": "to be exceptional, unusual, extraordinary", "note": "Sino-Korean; 이례 = unusual precedent + 적이다"}, {"ko": "당시", "en": "at that time, in those days", "note": "refers to a specific past time being discussed"}], "analysis": [{"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "Past tense formal-polite ending. 것이다 → 것이었습니다 = ''it was (a thing).'' 사실이었습니다 (it was a fact).", "example_in_sentence": "것이었습니다"}, {"type": "grammar", "label": "~(으)면서 (while)", "exp": "Simultaneous action ''while/as.'' 연기하다 → 연기하면서 = ''while acting/playing.'' 공부하다 → 공부하면서 (while studying).", "example_in_sentence": "연기하면서"}, {"type": "grammar", "label": "~적 (-ic / -al adjective suffix)", "exp": "Sino-Korean noun + 적 forms an adjective. 이례 + 적인 = ''exceptional/extraordinary.'' 일반적 (general); 효과적인 방법 (effective method).", "example_in_sentence": "이례적인"}, {"type": "grammar", "label": "~까지 (even)", "exp": "Here 까지 means ''even (going as far as)''. 네 번째 벽까지 허문 (even broke the fourth wall).", "example_in_sentence": "네 번째 벽까지"}]}, {"text": "《나를 사랑한 남자들》은 지금으로부터 100년도 훨씬 이전에 제작된 영화이지만, 네 번째 벽 허물기라는 기법의 기원을 확인할 수 있는 작품으로 기록되어 있습니다.", "translation": "Although ''Men Who Have Made Love to Me'' was made well over 100 years ago, it is recorded as a work that shows the origin of the technique of breaking the fourth wall.", "vocab": [{"ko": "제작되다", "en": "to be produced, to be made", "note": "passive form of 제작하다; used for films, products"}, {"ko": "기원", "en": "origin, beginning", "note": "the starting point or source of something"}, {"ko": "기록되다", "en": "to be recorded, to be documented", "note": "passive; appears in official or historical records"}], "analysis": [{"type": "grammar", "label": "~아/어 있다 (resultant state)", "exp": "Describes a state resulting from a completed action. 기록되다 → 기록되어 있다 = ''is (and remains) recorded.'' 문이 열려 있다 (the door is open).", "example_in_sentence": "기록되어 있습니다"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다/없다 (ability/possibility)", "exp": "Expresses ability or possibility. 확인하다 → 확인할 수 있다 = ''can confirm.'' 볼 수 없다 (cannot see).", "example_in_sentence": "확인할 수 있는"}, {"type": "grammar", "label": "~지만 (but)", "exp": "Contrastive conjunction ''but/however.'' 영화이다 → 영화이지만 = ''it is a film, but….'' 좋지만 비싸다 (it''s good but expensive).", "example_in_sentence": "영화이지만"}, {"type": "grammar", "label": "~(으)로 (means/direction)", "exp": "Indicates means, capacity, or result. 작품 + 으로 기록되다 = ''to be recorded as a work.'' 대표로 선출되다 (to be elected as representative).", "example_in_sentence": "작품으로 기록되어"}, {"type": "grammar", "label": "~(으)로부터 (from)", "exp": "Formal ''from''. 지금으로부터 100년 이전 (more than 100 years before now).", "example_in_sentence": "지금으로부터"}, {"type": "grammar", "label": "~도 (even)", "exp": "Here 도 means ''even''. 100년도 훨씬 이전에 (even well over 100 years ago).", "example_in_sentence": "100년도 훨씬 이전에"}, {"type": "grammar", "label": "~(이)라는 N", "exp": "''Called ~'' before a noun. 허물기 → 허물기라는 기법 (the technique called breaking the fourth wall).", "example_in_sentence": "네 번째 벽 허물기라는 기법"}]}], "version": "s6"}', vocab = '[{"ko": "바라보다", "en": "to look at, to gaze at", "note": "direct visual attention toward something"}, {"ko": "관객", "en": "audience, spectator", "note": "people watching a performance or film"}, {"ko": "기법", "en": "technique, method", "note": "specialized or artistic technique"}, {"ko": "허물다", "en": "to break down, to demolish", "note": "used figuratively here for ''breaking'' a barrier"}, {"ko": "장편", "en": "feature-length, full-length", "note": "refers to long-form works, especially films or novels"}, {"ko": "무성 영화", "en": "silent film", "note": "film with no synchronized recorded dialogue"}, {"ko": "최초", "en": "the first, the earliest", "note": "Sino-Korean noun meaning ''for the first time / the very first''"}, {"ko": "주연", "en": "lead role, starring role", "note": "the main actor/actress in a film or play"}, {"ko": "허구", "en": "fiction, fabrication", "note": "something invented, not real"}, {"ko": "연기하다", "en": "to act, to perform", "note": "to portray a character in film or theater"}, {"ko": "서사", "en": "narrative, epic", "note": "the story or storytelling element of a work"}, {"ko": "바탕", "en": "basis, foundation", "note": "the underlying base or foundation something is built on"}, {"ko": "자기 자신", "en": "oneself, one''s own self", "note": "emphatic reflexive pronoun"}, {"ko": "실존", "en": "real existence, actual existence", "note": "Sino-Korean; refers to actually existing persons or things"}, {"ko": "사례", "en": "case, example, instance", "note": "a specific occurrence used as an example"}, {"ko": "이례적이다", "en": "to be exceptional, unusual, extraordinary", "note": "Sino-Korean; 이례 = unusual precedent + 적이다"}, {"ko": "당시", "en": "at that time, in those days", "note": "refers to a specific past time being discussed"}, {"ko": "제작되다", "en": "to be produced, to be made", "note": "passive form of 제작하다; used for films, products"}, {"ko": "기원", "en": "origin, beginning", "note": "the starting point or source of something"}, {"ko": "기록되다", "en": "to be recorded, to be documented", "note": "passive; appears in official or historical records"}]', grammar = '{"patterns": [{"name": "~(으)며", "level": "Intermediate", "exp": "Written connector meaning ''while / and''. 바라보다 → 바라보며 (while looking at).", "ex_ko": "영화에서 배우가 카메라를 직접 바라보며 관객에게 말을 거는 기법을 ''네 번째 벽 허물기''라고 합니다.", "ex_en": "The technique in which an actor directly looks at the camera and speaks to the audience is called ''breaking the fourth wall.''"}, {"name": "~에서 (location/source)", "level": "Intermediate", "exp": "Marks the location where an action takes place. 영화 + 에서 = ''in (a/the) film.'' 학교에서 공부하다 (study at school).", "ex_ko": "영화에서 배우가 카메라를 직접 바라보며 관객에게 말을 거는 기법을 ''네 번째 벽 허물기''라고 합니다.", "ex_en": "The technique in which an actor directly looks at the camera and speaks to the audience is called ''breaking the fourth wall.''"}, {"name": "~에게/한테 (to person)", "level": "Intermediate", "exp": "Indirect object marker for animate recipients. 관객 + 에게 = ''to the audience.'' 친구에게 편지를 쓰다 (write a letter to a friend).", "ex_ko": "영화에서 배우가 카메라를 직접 바라보며 관객에게 말을 거는 기법을 ''네 번째 벽 허물기''라고 합니다.", "ex_en": "The technique in which an actor directly looks at the camera and speaks to the audience is called ''breaking the fourth wall.''"}, {"name": "~(으)로 (means/direction)", "level": "Intermediate", "exp": "Indicates means, capacity, or result. 작품 + 으로 기록되다 = ''to be recorded as a work.'' 대표로 선출되다 (to be elected as representative).", "ex_ko": "이 기법을 장편 서사 영화 최초로 사용한 작품이 1918년 무성 영화 《나를 사랑한 남자들》이라고 알려져 있습니다.", "ex_en": "The work that first used this technique in a feature-length narrative film is known to be the 1918 silent film ''Men Who Have Made Love to Me.''"}, {"name": "~(이)라고 알려져 있다", "level": "Intermediate", "exp": "''Is known to be ~''. 《나를 사랑한 남자들》이라고 알려져 있습니다 (is known to be the film ''Men Who Have Made Love to Me'').", "ex_ko": "이 기법을 장편 서사 영화 최초로 사용한 작품이 1918년 무성 영화 《나를 사랑한 남자들》이라고 알려져 있습니다.", "ex_en": "The work that first used this technique in a feature-length narrative film is known to be the 1918 silent film ''Men Who Have Made Love to Me.''"}, {"name": "~았/었/였습니다 (past formal)", "level": "Intermediate", "exp": "Past tense formal-polite ending. 인물이다 → 인물이었습니다 = ''was a person/character.'' 선생님이었습니다 (was a teacher).", "ex_ko": "이 영화의 주연은 배우 메리 맥레인이었습니다.", "ex_en": "The lead role in this film was actress Mary MacLane."}, {"name": "~(으)면서 (while)", "level": "Intermediate", "exp": "Simultaneous action ''while/as.'' 연기하다 → 연기하면서 = ''while acting/playing.'' 공부하다 → 공부하면서 (while studying).", "ex_ko": "그녀는 실제 자신을 모델로 한 허구의 인물을 연기하면서, 서사 장면 밖으로 나와 카메라를 향해 직접 말을 걸었습니다.", "ex_en": "While playing a fictional character modeled on her real self, she stepped outside the narrative scenes and spoke directly toward the camera."}, {"name": "~을/를 N(으)로 한", "level": "Intermediate", "exp": "''Using ~ as N / modeled on ~'' before a noun. 자신을 모델로 한 인물 (a character modeled on herself).", "ex_ko": "그녀는 실제 자신을 모델로 한 허구의 인물을 연기하면서, 서사 장면 밖으로 나와 카메라를 향해 직접 말을 걸었습니다.", "ex_en": "While playing a fictional character modeled on her real self, she stepped outside the narrative scenes and spoke directly toward the camera."}, {"name": "~아/어 (and then)", "level": "Intermediate", "exp": "Links actions in order: ''did ~ and then''. 나오다 → 나와 (came out and ...).", "ex_ko": "그녀는 실제 자신을 모델로 한 허구의 인물을 연기하면서, 서사 장면 밖으로 나와 카메라를 향해 직접 말을 걸었습니다.", "ex_en": "While playing a fictional character modeled on her real self, she stepped outside the narrative scenes and spoke directly toward the camera."}, {"name": "~을/를 향해(서) / 향한 (toward / aimed at)", "level": "Intermediate", "exp": "Indicates direction or aim. 카메라 + 를 향해 = ''toward the camera.'' 미래를 향해 나아가다 (move toward the future).", "ex_ko": "그녀는 실제 자신을 모델로 한 허구의 인물을 연기하면서, 서사 장면 밖으로 나와 카메라를 향해 직접 말을 걸었습니다.", "ex_en": "While playing a fictional character modeled on her real self, she stepped outside the narrative scenes and spoke directly toward the camera."}, {"name": "~히 (adverb suffix, Sino-Korean)", "level": "Intermediate", "exp": "Adverbializer for Sino-Korean adjective stems. 완전하다 → 완전히 = ''completely.'' 정확하다 → 정확히 (accurately).", "ex_ko": "메리 맥레인이 연기한 인물은 완전히 새로운 캐릭터가 아니라, 자기 자신을 바탕으로 한 인물이었습니다.", "ex_en": "The character Mary MacLane played was not an entirely new character, but rather one based on herself."}, {"name": "~을/를 바탕으로 한", "level": "Intermediate", "exp": "''Based on ~'' before a noun. 자기 자신을 바탕으로 한 인물 (a character based on herself).", "ex_ko": "메리 맥레인이 연기한 인물은 완전히 새로운 캐릭터가 아니라, 자기 자신을 바탕으로 한 인물이었습니다.", "ex_en": "The character Mary MacLane played was not an entirely new character, but rather one based on herself."}, {"name": "ㅂ 불규칙 (ㅂ irregular)", "level": "Intermediate", "exp": "새롭다 is ㅂ-irregular: ㅂ becomes 우 before a vowel ending. 새롭다 → 새로운 (new).", "ex_ko": "메리 맥레인이 연기한 인물은 완전히 새로운 캐릭터가 아니라, 자기 자신을 바탕으로 한 인물이었습니다.", "ex_en": "The character Mary MacLane played was not an entirely new character, but rather one based on herself."}, {"name": "~적 (-ic / -al adjective suffix)", "level": "Intermediate", "exp": "Sino-Korean noun + 적 forms an adjective. 이례 + 적인 = ''exceptional/extraordinary.'' 일반적 (general); 효과적인 방법 (effective method).", "ex_ko": "이처럼 실존 인물이 자신을 직접 연기하면서 네 번째 벽까지 허문 사례는 당시로서는 매우 이례적인 것이었습니다.", "ex_en": "A case like this, in which a real person directly played themselves and even broke the fourth wall, was extremely unusual for the time."}, {"name": "~까지 (even)", "level": "Intermediate", "exp": "Here 까지 means ''even (going as far as)''. 네 번째 벽까지 허문 (even broke the fourth wall).", "ex_ko": "이처럼 실존 인물이 자신을 직접 연기하면서 네 번째 벽까지 허문 사례는 당시로서는 매우 이례적인 것이었습니다.", "ex_en": "A case like this, in which a real person directly played themselves and even broke the fourth wall, was extremely unusual for the time."}]}', updated_at = now() where article_id = 'mpi1lilglpa8' and md5(translation) = '22a6f17972085169a464b44cbd7c203c';
update public.article_cache set translation = '{"texts": ["In 2017, two orangutans came out of the fence at Perth Zoo in Australia. The zoo immediately locked the door.", "A 5-year-old male orangutan fell into the flower bed next to the fence. It had come out to the outside of the fence.", "Then the mother orangutan went to the baby. She had gone to fetch the baby.", "The mother used the visitor walkway and returned to the exhibit area. She came back on her own."], "sentences": [{"text": "2017년에 호주 퍼스 동물원에서 오랑우탄 두 마리가 울타리 밖으로 나왔어요.", "translation": "In 2017, two orangutans got out of their enclosure at Perth Zoo in Australia.", "vocab": [{"ko": "동물원", "en": "zoo", "note": ""}, {"ko": "울타리", "en": "fence / enclosure", "note": ""}, {"ko": "나오다", "en": "to come out", "note": "나오다 = 나 (out) + 오다 (come)"}], "analysis": [{"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite ending. 나오다 → stem 나오 + 았어요 → contracts to 나왔어요.", "example_in_sentence": "나왔어요"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle attached to a noun ending in a vowel. 마리 → 마리가.", "example_in_sentence": "두 마리가"}, {"type": "grammar", "label": "~에서 (location/source)", "exp": "Marks the location where an action takes place. 동물원 + 에서 = at/in the zoo.", "example_in_sentence": "동물원에서"}, {"type": "grammar", "label": "~에 (location/time)", "exp": "Marks a point in time. 2017년 + 에 = in (the year) 2017.", "example_in_sentence": "2017년에"}, {"type": "grammar", "label": "~(으)로 (means/direction)", "exp": "Marks direction toward which movement occurs. 밖 + 으로 = to the outside / out.", "example_in_sentence": "밖으로"}]}, {"text": "동물원은 바로 문을 잠갔어요.", "translation": "The zoo immediately locked the door.", "vocab": [{"ko": "잠그다", "en": "to lock", "note": "잠그다 → 잠갔어요 (past); ㅡ drops before 아/어"}, {"ko": "바로", "en": "immediately / right away", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite ending. 잠그다 → stem 잠그 + 았어요 → ㅡ drops → 잠갔어요.", "example_in_sentence": "잠갔어요"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "Direct object particle. 문 ends in a consonant → 문 + 을 = 문을.", "example_in_sentence": "문을"}, {"type": "grammar", "label": "~은/는 (topic marker)", "exp": "Topic particle. 동물원 ends in consonant ㄴ → 동물원 + 은 = 동물원은.", "example_in_sentence": "동물원은"}]}, {"text": "5살 수컷 오랑우탄이 울타리 옆 화단으로 떨어졌어요.", "translation": "A 5-year-old male orangutan fell into the flower bed next to the fence.", "vocab": [{"ko": "수컷", "en": "male (animal)", "note": "opposite: 암컷 (female animal)"}, {"ko": "화단", "en": "flower bed", "note": ""}, {"ko": "떨어지다", "en": "to fall / to drop", "note": "떨어지다 → 떨어졌어요 (past)"}], "analysis": [{"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite ending. 떨어지다 → stem 떨어지 + 었어요 → 떨어졌어요.", "example_in_sentence": "떨어졌어요"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle. 오랑우탄 ends in consonant ㄴ → 오랑우탄 + 이 = 오랑우탄이.", "example_in_sentence": "오랑우탄이"}, {"type": "grammar", "label": "~(으)로 (means/direction)", "exp": "Marks direction of movement. 화단 ends in consonant ㄴ → 화단 + 으로 = 화단으로 (into the flower bed).", "example_in_sentence": "화단으로"}]}, {"text": "울타리 밖으로 나온 거예요.", "translation": "It had gotten outside the fence.", "vocab": [{"ko": "밖", "en": "outside", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)로 (means/direction)", "exp": "Marks direction of movement. 밖 ends in consonant ㄱ → 밖 + 으로 = 밖으로 (to the outside).", "example_in_sentence": "밖으로"}, {"type": "expression", "label": "~(으)ㄴ 거예요", "exp": "Explains a situation: ''it''s that ~''. 나오다 → 나온 거예요 (it had come out).", "example_in_sentence": "나온 거예요"}]}, {"text": "그러자 어미 오랑우탄이 아기에게 갔어요.", "translation": "Then the mother orangutan went to the baby.", "vocab": [{"ko": "어미", "en": "mother (animal)", "note": "used for animal mothers; 엄마 is used for humans"}, {"ko": "가다", "en": "to go", "note": "가다 → 갔어요 (past)"}, {"ko": "그러자", "en": "then / at that moment", "note": "connects two events: ''and then / upon that''"}], "analysis": [{"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite ending. 가다 → stem 가 + 았어요 → vowel contracts → 갔어요.", "example_in_sentence": "갔어요"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle. 오랑우탄 ends in consonant ㄴ → 오랑우탄 + 이 = 오랑우탄이.", "example_in_sentence": "오랑우탄이"}, {"type": "grammar", "label": "~에게/한테 (to person)", "exp": "Indirect object marker for animate beings. 아기 + 에게 = to the baby.", "example_in_sentence": "아기에게"}]}, {"text": "아기를 데리러 간 거예요.", "translation": "She had gone to fetch the baby.", "vocab": [{"ko": "데리다", "en": "to bring (a person/animal) along", "note": "데리러 가다 = go to pick up / go to get someone"}], "analysis": [{"type": "grammar", "label": "~(으)러 (purpose with movement)", "exp": "Expresses purpose of movement. 데리다 → stem 데리 + 러 + 가다 = 데리러 가다 (go to fetch/bring).", "example_in_sentence": "데리러"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "Direct object particle. 아기 ends in vowel → 아기 + 를 = 아기를.", "example_in_sentence": "아기를"}, {"type": "expression", "label": "~(으)ㄴ 거예요", "exp": "Explains or clarifies the reason for a prior action. 가다 → 간 거예요 = ''It is that she went (to do something)''.", "example_in_sentence": "간 거예요"}]}, {"text": "어미는 방문객 보행로를 이용해서 전시 구역으로 돌아왔어요.", "translation": "The mother used the visitor walkway and returned to the exhibit area.", "vocab": [{"ko": "방문객", "en": "visitor", "note": ""}, {"ko": "보행로", "en": "walkway / footpath", "note": "보행 (walking) + 로 (road/path)"}, {"ko": "이용하다", "en": "to use / to make use of", "note": "이용해서 = using (and then)"}, {"ko": "돌아오다", "en": "to return / to come back", "note": "돌아오다 → 돌아왔어요 (past)"}], "analysis": [{"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite ending. 돌아오다 → stem 돌아오 + 았어요 → contracts → 돌아왔어요.", "example_in_sentence": "돌아왔어요"}, {"type": "grammar", "label": "~아/어서 (cause / sequence)", "exp": "Expresses sequence: ''and then / by doing''. 이용하다 → stem 이용하 + 여서 → contracts → 이용해서 (by using / using and then).", "example_in_sentence": "이용해서"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "Direct object particle. 보행로 ends in vowel → 보행로 + 를 = 보행로를.", "example_in_sentence": "보행로를"}, {"type": "grammar", "label": "~은/는 (topic marker)", "exp": "Topic particle. 어미 ends in vowel → 어미 + 는 = 어미는.", "example_in_sentence": "어미는"}, {"type": "grammar", "label": "~(으)로 (means/direction)", "exp": "Marks direction of return. 구역 ends in consonant ㄱ → 구역 + 으로 = 구역으로 (to the exhibit area).", "example_in_sentence": "전시 구역으로"}]}, {"text": "스스로 돌아온 거예요.", "translation": "She came back on her own.", "vocab": [{"ko": "스스로", "en": "by oneself / on one''s own", "note": "adverb; emphasises self-directed action"}], "analysis": [{"type": "expression", "label": "~(으)ㄴ 거예요", "exp": "Clarifies or explains a fact with mild emphasis. 돌아오다 → 돌아온 거예요 = ''It is that she came back (on her own)''.", "example_in_sentence": "돌아온 거예요"}]}], "version": "s6"}', vocab = '[{"ko": "동물원", "en": "zoo", "note": ""}, {"ko": "울타리", "en": "fence / enclosure", "note": ""}, {"ko": "나오다", "en": "to come out", "note": "나오다 = 나 (out) + 오다 (come)"}, {"ko": "잠그다", "en": "to lock", "note": "잠그다 → 잠갔어요 (past); ㅡ drops before 아/어"}, {"ko": "바로", "en": "immediately / right away", "note": ""}, {"ko": "수컷", "en": "male (animal)", "note": "opposite: 암컷 (female animal)"}, {"ko": "화단", "en": "flower bed", "note": ""}, {"ko": "떨어지다", "en": "to fall / to drop", "note": "떨어지다 → 떨어졌어요 (past)"}, {"ko": "밖", "en": "outside", "note": ""}, {"ko": "어미", "en": "mother (animal)", "note": "used for animal mothers; 엄마 is used for humans"}, {"ko": "가다", "en": "to go", "note": "가다 → 갔어요 (past)"}, {"ko": "그러자", "en": "then / at that moment", "note": "connects two events: ''and then / upon that''"}, {"ko": "데리다", "en": "to bring (a person/animal) along", "note": "데리러 가다 = go to pick up / go to get someone"}, {"ko": "방문객", "en": "visitor", "note": ""}, {"ko": "보행로", "en": "walkway / footpath", "note": "보행 (walking) + 로 (road/path)"}, {"ko": "이용하다", "en": "to use / to make use of", "note": "이용해서 = using (and then)"}, {"ko": "돌아오다", "en": "to return / to come back", "note": "돌아오다 → 돌아왔어요 (past)"}, {"ko": "스스로", "en": "by oneself / on one''s own", "note": "adverb; emphasises self-directed action"}]', grammar = '{"patterns": [{"name": "~았/었/였어요 (past polite)", "level": "Beginner", "exp": "Past polite ending. 가다 → stem 가 + 았어요 → vowel contracts → 갔어요.", "ex_ko": "2017년에 호주 퍼스 동물원에서 오랑우탄 두 마리가 울타리 밖으로 나왔어요.", "ex_en": "In 2017, two orangutans got out of their enclosure at Perth Zoo in Australia."}, {"name": "~이/가 (subject marker)", "level": "Beginner", "exp": "Subject particle attached to a noun ending in a vowel. 마리 → 마리가.", "ex_ko": "2017년에 호주 퍼스 동물원에서 오랑우탄 두 마리가 울타리 밖으로 나왔어요.", "ex_en": "In 2017, two orangutans got out of their enclosure at Perth Zoo in Australia."}, {"name": "~에서 (location/source)", "level": "Beginner", "exp": "Marks the location where an action takes place. 동물원 + 에서 = at/in the zoo.", "ex_ko": "2017년에 호주 퍼스 동물원에서 오랑우탄 두 마리가 울타리 밖으로 나왔어요.", "ex_en": "In 2017, two orangutans got out of their enclosure at Perth Zoo in Australia."}, {"name": "~(으)로 (means/direction)", "level": "Beginner", "exp": "Marks direction of movement. 화단 ends in consonant ㄴ → 화단 + 으로 = 화단으로 (into the flower bed).", "ex_ko": "2017년에 호주 퍼스 동물원에서 오랑우탄 두 마리가 울타리 밖으로 나왔어요.", "ex_en": "In 2017, two orangutans got out of their enclosure at Perth Zoo in Australia."}, {"name": "~을/를 (object marker)", "level": "Beginner", "exp": "Direct object particle. 문 ends in a consonant → 문 + 을 = 문을.", "ex_ko": "동물원은 바로 문을 잠갔어요.", "ex_en": "The zoo immediately locked the door."}, {"name": "~은/는 (topic marker)", "level": "Beginner", "exp": "Topic particle. 동물원 ends in consonant ㄴ → 동물원 + 은 = 동물원은.", "ex_ko": "동물원은 바로 문을 잠갔어요.", "ex_en": "The zoo immediately locked the door."}, {"name": "~에게/한테 (to person)", "level": "Beginner", "exp": "Indirect object marker for animate beings. 아기 + 에게 = to the baby.", "ex_ko": "그러자 어미 오랑우탄이 아기에게 갔어요.", "ex_en": "Then the mother orangutan went to the baby."}, {"name": "~(으)러 (purpose with movement)", "level": "Beginner", "exp": "Expresses purpose of movement. 데리다 → stem 데리 + 러 + 가다 = 데리러 가다 (go to fetch/bring).", "ex_ko": "아기를 데리러 간 거예요.", "ex_en": "She had gone to fetch the baby."}, {"name": "~아/어서 (cause / sequence)", "level": "Beginner", "exp": "Expresses sequence: ''and then / by doing''. 이용하다 → stem 이용하 + 여서 → contracts → 이용해서 (by using / using and then).", "ex_ko": "어미는 방문객 보행로를 이용해서 전시 구역으로 돌아왔어요.", "ex_en": "The mother used the visitor walkway and returned to the exhibit area."}]}', updated_at = now() where article_id = 'mpi1m1cjdqrp' and md5(translation) = '15dc6f726eb77f4e2d11606154e369d1';
update public.article_cache set translation = '{"texts": ["Kendrick Lamar made history at the Grammy Awards ceremony. At the 2026 awards ceremony, he received five Grammy Awards.", "With this award win, Kendrick Lamar''s total Grammy Award count became 27. With this record, he became a rapper who received more Grammys than Jay-Z.", "Kendrick Lamar is now the rapper who has received the most awards in Grammy history. Until now, Jay-Z had been holding this position.", "Kendrick Lamar''s total Grammy Award count is 27. This number is the highest record among rappers."], "sentences": [{"text": "켄드릭 라마가 그래미 시상식에서 역사를 만들었어요.", "translation": "Kendrick Lamar made history at the Grammy Awards ceremony.", "vocab": [{"ko": "만들다", "en": "to make; to create", "note": ""}], "analysis": [{"type": "grammar", "label": "~이/가 (subject marker)", "exp": "subject particle. 켄드릭 라마가 (Kendrick Lamar [subject]).", "example_in_sentence": "켄드릭 라마가"}, {"type": "grammar", "label": "~에서 (action-location / source / starting point)", "exp": "location of an action. 그래미 시상식에서 (at the Grammy Awards ceremony) — dynamic action 만들다 takes ~에서.", "example_in_sentence": "그래미 시상식에서"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "direct object particle. 역사를 (history [object]).", "example_in_sentence": "역사를"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "past polite ending. 만들다 + 었어요 → 만들었어요 (made).", "example_in_sentence": "만들었어요"}]}, {"text": "2026년 시상식에서 그래미상을 다섯 개 받았어요.", "translation": "At the 2026 awards ceremony, he received five Grammy Awards.", "vocab": [{"ko": "받다", "en": "to receive; to get", "note": ""}], "analysis": [{"type": "grammar", "label": "~에서 (action-location / source / starting point)", "exp": "location of an action. 시상식에서 (at the awards ceremony) — dynamic verb 받다 takes ~에서.", "example_in_sentence": "시상식에서"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "direct object particle. 그래미상을 (Grammy Awards [object]).", "example_in_sentence": "그래미상을"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "past polite ending. 받다 + 았어요 → 받았어요 (received).", "example_in_sentence": "받았어요"}]}, {"text": "이번 수상으로 켄드릭 라마의 그래미 총 수상 수는 27개가 됐어요.", "translation": "With this award win, Kendrick Lamar''s total Grammy Award count became 27.", "vocab": [{"ko": "수상", "en": "winning an award", "note": ""}, {"ko": "되다", "en": "to become", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)로 (means / direction / transformation)", "exp": "means or method. 이번 수상으로 (by means of this award win / as a result of this award).", "example_in_sentence": "이번 수상으로"}, {"type": "grammar", "label": "~의 (possessive / relational)", "exp": "possession. 켄드릭 라마의 (Kendrick Lamar''s).", "example_in_sentence": "켄드릭 라마의"}, {"type": "grammar", "label": "~은/는 (topic marker)", "exp": "topic particle. 그래미 총 수상 수는 (as for the total Grammy count).", "example_in_sentence": "그래미 총 수상 수는"}, {"type": "grammar", "label": "~이/가 되다", "exp": "With 되다, 이/가 marks the result: 27개가 됐어요 (became 27).", "example_in_sentence": "27개가 됐어요"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "past polite ending. 되다 + 었어요 → 됐어요 (became) [vowel-contracted form].", "example_in_sentence": "됐어요"}]}, {"text": "이 기록으로 그는 제이지보다 더 많은 그래미를 받은 래퍼가 됐어요.", "translation": "With this record, he became a rapper who received more Grammys than Jay-Z.", "vocab": [{"ko": "기록", "en": "record", "note": ""}, {"ko": "많다", "en": "to be many; to be much", "note": ""}, {"ko": "받다", "en": "to receive; to get", "note": ""}, {"ko": "되다", "en": "to become", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)로 (means / direction / transformation)", "exp": "means or method. 이 기록으로 (by means of this record / as a result of this record).", "example_in_sentence": "이 기록으로"}, {"type": "grammar", "label": "~보다 (comparison: than)", "exp": "comparative particle. 제이지보다 (than Jay-Z) — 더 많은 with 보다 forms comparison.", "example_in_sentence": "제이지보다"}, {"type": "grammar", "label":