update public.article_cache set translation = '{"texts": ["Lions once lived across most of Africa and vast regions of Asia. Their distribution reportedly extended as far as Hungary and Ukraine. In ancient Greece, lions were not a foreign species but a native animal. According to historical records, lions were reportedly a common sight in Greece at that time. Considering that today lions'' habitats have been greatly reduced to only some regions of Africa, their past distribution range seems to have been very wide. The fact that lions lived on the European mainland is quite different from current common knowledge.", "South Korea faces severe teacher shortage; school classes disrupted", "What is an \"anxiety bag\"? A popular trend", "\"Talking pig\" becomes an SNS star", "The United States and China resume talks over trade issues", "\"Nothing maxing\" trend of doing nothing spreads"], "sentences": [{"text": "사자는 한때 아프리카 대부분의 지역과 아시아의 넓은 지역에 걸쳐 살았습니다.", "translation": "Lions once lived across most of Africa and vast regions of Asia.", "vocab": [{"ko": "한때", "en": "once; at one time"}, {"ko": "걸치다", "en": "to span; to extend over"}], "analysis": [{"type": "grammar", "label": "~았/었습니다", "exp": "Past tense polite ending. The stem 살 combines with the past marker 았 and polite ending 습니다.", "example_in_sentence": "살았습니다"}, {"type": "expression", "label": "~에 걸쳐", "exp": "''Across / spanning (an area or period)''. 넓은 지역에 걸쳐 살았습니다 (lived across wide regions).", "example_in_sentence": "넓은 지역에 걸쳐"}]}, {"text": "그 분포는 헝가리와 우크라이나까지 이어졌다고 합니다.", "translation": "Their distribution is said to have extended as far as Hungary and Ukraine.", "vocab": [{"ko": "분포", "en": "distribution"}, {"ko": "이어지다", "en": "to extend; to stretch"}], "analysis": [{"type": "grammar", "label": "~았/었다고 하다", "exp": "Indirect reported speech in past tense. The past form 이어졌다 is marked with 고, then 하다 in polite form 합니다.", "example_in_sentence": "이어졌다고 합니다"}, {"type": "expression", "label": "~까지 (as far as)", "exp": "''As far as / up to''. 우크라이나까지 이어졌다 (extended as far as Ukraine).", "example_in_sentence": "헝가리와 우크라이나까지"}]}, {"text": "고대 그리스에서도 사자는 외래종이 아닌 토착 동물이었습니다.", "translation": "In ancient Greece as well, lions were native animals, not foreign species.", "vocab": [{"ko": "고대", "en": "ancient; antiquity"}, {"ko": "외래종", "en": "foreign/invasive species"}, {"ko": "토착", "en": "native; indigenous"}], "analysis": [{"type": "grammar", "label": "~이/가 아닌 N", "exp": "''Not ~'' before a noun (from 이/가 아니다). 외래종이 아닌 토착 동물 (a native animal, not a foreign species).", "example_in_sentence": "외래종이 아닌"}, {"type": "grammar", "label": "~이었습니다", "exp": "Past tense of copula 이다. The stem 이 + past marker 었 + polite ending 습니다.", "example_in_sentence": "이었습니다"}]}, {"text": "역사적 기록에 따르면, 사자는 그 시대 그리스에서 흔히 볼 수 있는 동물이었다고 합니다.", "translation": "According to historical records, lions were reportedly a common sight in Greece at that time.", "vocab": [{"ko": "기록", "en": "record; documentation"}, {"ko": "따르다", "en": "to follow; (~에 따르면) according to"}, {"ko": "흔히", "en": "commonly; frequently"}], "analysis": [{"type": "expression", "label": "N에 따르면", "exp": "Expression meaning ''according to; based on.'' The particle 에 + 따르다 in conditional form.", "example_in_sentence": "역사적 기록에 따르면"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "''Can''. 보다 → 볼 수 있는 동물 (animals one could see).", "example_in_sentence": "볼 수 있는"}, {"type": "grammar", "label": "~았/었다고 하다", "exp": "Indirect reported speech in past. The past form 이었다 + 고 + 하다 in polite form.", "example_in_sentence": "이었다고 합니다"}]}, {"text": "오늘날 사자의 서식지가 아프리카 일부 지역으로 크게 줄어든 것을 생각하면, 과거의 분포 범위는 매우 넓었던 것 같습니다.", "translation": "Considering that the lion''s habitat today has shrunk greatly to only some parts of Africa, its range in the past seems to have been very wide.", "vocab": [{"ko": "서식지", "en": "habitat"}, {"ko": "줄어들다", "en": "to shrink; to decrease"}, {"ko": "범위", "en": "range; scope"}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ 것을 생각하면", "exp": "''Considering (the fact) that ~''. 줄어들다 → 줄어든 것을 생각하면 (considering that it has shrunk).", "example_in_sentence": "줄어든 것을 생각하면"}, {"type": "expression", "label": "~았/었던 것 같다", "exp": "''It seems that ~ was''. 넓다 → 넓었던 것 같습니다 (seems to have been wide).", "example_in_sentence": "넓었던 것 같습니다"}]}, {"text": "유럽 본토에서 사자가 살았다는 사실은 현재의 상식과는 꽤 다릅니다.", "translation": "The fact that lions lived on the European mainland is quite different from current common knowledge.", "vocab": [{"ko": "본토", "en": "mainland"}, {"ko": "사실", "en": "fact"}, {"ko": "상식", "en": "common sense; common knowledge"}], "analysis": [{"type": "grammar", "label": "~았/었다는 N", "exp": "Quotes a fact to describe a noun. 살다 → 살았다는 사실 (the fact that (lions) lived).", "example_in_sentence": "살았다는 사실"}, {"type": "grammar", "label": "~과/와는", "exp": "''(Compared) with'', plus 는 for contrast. 상식과는 다릅니다 (is different from common knowledge).", "example_in_sentence": "상식과는"}, {"type": "expression", "label": "꽤 다르다", "exp": "Expression meaning ''quite/considerably different.'' The adverb 꽤 (quite) modifies the adjective 다르다.", "example_in_sentence": "꽤 다릅니다"}]}], "version": "s6"}', vocab = '[{"ko": "한때", "en": "once; at one time", "note": ""}, {"ko": "걸치다", "en": "to span; to extend over", "note": ""}, {"ko": "분포", "en": "distribution", "note": ""}, {"ko": "이어지다", "en": "to extend; to stretch", "note": ""}, {"ko": "고대", "en": "ancient; antiquity", "note": ""}, {"ko": "외래종", "en": "foreign/invasive species", "note": ""}, {"ko": "토착", "en": "native; indigenous", "note": ""}, {"ko": "기록", "en": "record; documentation", "note": ""}, {"ko": "따르다", "en": "to follow; (~에 따르면) according to", "note": ""}, {"ko": "흔히", "en": "commonly; frequently", "note": ""}, {"ko": "서식지", "en": "habitat", "note": ""}, {"ko": "줄어들다", "en": "to shrink; to decrease", "note": ""}, {"ko": "범위", "en": "range; scope", "note": ""}, {"ko": "본토", "en": "mainland", "note": ""}, {"ko": "사실", "en": "fact", "note": ""}, {"ko": "상식", "en": "common sense; common knowledge", "note": ""}, {"ko": "사자", "en": "lion", "note": ""}, {"ko": "대부분", "en": "most; majority", "note": ""}, {"ko": "넓다", "en": "wide; vast", "note": ""}, {"ko": "헝가리", "en": "Hungary", "note": ""}, {"ko": "우크라이나", "en": "Ukraine", "note": ""}, {"ko": "그리스", "en": "Greece", "note": ""}, {"ko": "역사", "en": "history", "note": ""}, {"ko": "시대", "en": "age; era; period", "note": ""}, {"ko": "흔하다", "en": "common; frequent", "note": ""}, {"ko": "오늘날", "en": "today; nowadays", "note": ""}, {"ko": "일부", "en": "some; part", "note": ""}, {"ko": "유럽", "en": "Europe", "note": ""}, {"ko": "살다", "en": "to live; to dwell", "note": ""}]', grammar = '{"patterns": [{"name": "~았/었습니다", "level": "Intermediate", "exp": "Past tense polite ending. The stem 살 combines with the past marker 았 and polite ending 습니다.", "ex_ko": "사자는 한때 아프리카 대부분의 지역과 아시아의 넓은 지역에 걸쳐 살았습니다.", "ex_en": "Lions once lived across most of Africa and vast regions of Asia."}, {"name": "~았/었다고 하다", "level": "Intermediate", "exp": "Indirect reported speech in past tense. The past form 이어졌다 is marked with 고, then 하다 in polite form 합니다.", "ex_ko": "그 분포는 헝가리와 우크라이나까지 이어졌다고 합니다.", "ex_en": "Their distribution is said to have extended as far as Hungary and Ukraine."}, {"name": "~이/가 아닌 N", "level": "Intermediate", "exp": "''Not ~'' before a noun (from 이/가 아니다). 외래종이 아닌 토착 동물 (a native animal, not a foreign species).", "ex_ko": "고대 그리스에서도 사자는 외래종이 아닌 토착 동물이었습니다.", "ex_en": "In ancient Greece as well, lions were native animals, not foreign species."}, {"name": "~이었습니다", "level": "Intermediate", "exp": "Past tense of copula 이다. The stem 이 + past marker 었 + polite ending 습니다.", "ex_ko": "고대 그리스에서도 사자는 외래종이 아닌 토착 동물이었습니다.", "ex_en": "In ancient Greece as well, lions were native animals, not foreign species."}, {"name": "~(으)ㄹ 수 있다", "level": "Intermediate", "exp": "''Can''. 보다 → 볼 수 있는 동물 (animals one could see).", "ex_ko": "역사적 기록에 따르면, 사자는 그 시대 그리스에서 흔히 볼 수 있는 동물이었다고 합니다.", "ex_en": "According to historical records, lions were reportedly a common sight in Greece at that time."}, {"name": "~(으)ㄴ 것을 생각하면", "level": "Intermediate", "exp": "''Considering (the fact) that ~''. 줄어들다 → 줄어든 것을 생각하면 (considering that it has shrunk).", "ex_ko": "오늘날 사자의 서식지가 아프리카 일부 지역으로 크게 줄어든 것을 생각하면, 과거의 분포 범위는 매우 넓었던 것 같습니다.", "ex_en": "Considering that the lion''s habitat today has shrunk greatly to only some parts of Africa, its range in the past seems to have been very wide."}, {"name": "~았/었다는 N", "level": "Intermediate", "exp": "Quotes a fact to describe a noun. 살다 → 살았다는 사실 (the fact that (lions) lived).", "ex_ko": "유럽 본토에서 사자가 살았다는 사실은 현재의 상식과는 꽤 다릅니다.", "ex_en": "The fact that lions lived on the European mainland is quite different from current common knowledge."}, {"name": "~과/와는", "level": "Intermediate", "exp": "''(Compared) with'', plus 는 for contrast. 상식과는 다릅니다 (is different from common knowledge).", "ex_ko": "유럽 본토에서 사자가 살았다는 사실은 현재의 상식과는 꽤 다릅니다.", "ex_en": "The fact that lions lived on the European mainland is quite different from current common knowledge."}]}', updated_at = now() where article_id = 'mpi1msss84k0' and md5(translation) = '1e93f390cde533a9a02e7c7a0e3b8a23';
update public.article_cache set translation = '{"texts": ["The SpongeBob SquarePants animation episode ''Midlife Crisis'' has been removed from Nickelodeon''s broadcast schedule and Paramount+. The reason for the removal is that the episode contains a ''panty raid'' scene.", "''Panty raid'' is an expression that refers to a prank of secretly stealing someone else''s underwear. The broadcast was discontinued as the scene was deemed unsuitable for child-targeted content.", "This episode can no longer be seen on either Nickelodeon channel or streaming platform Paramount+. Because SpongeBob is a series that has been broadcast for a long time targeting child viewers, this decision appears to have been made."], "sentences": [{"text": "애니메이션 시리즈 스펀지밥의 에피소드 ''중년의 위기''가 니켈로디언의 방영 목록과 파라마운트+에서 삭제되었습니다.", "translation": "The SpongeBob SquarePants animation episode ''Midlife Crisis'' has been removed from Nickelodeon''s broadcast schedule and Paramount+.", "vocab": [{"ko": "애니메이션", "en": "animation", "note": ""}, {"ko": "시리즈", "en": "series", "note": ""}, {"ko": "에피소드", "en": "episode", "note": ""}, {"ko": "삭제되다", "en": "to be deleted; to be removed", "note": ""}], "analysis": [{"type": "grammar", "label": "~과/와 (and — listing)", "exp": "Listing conjunction connecting two nouns. 목록과 파라마운트+ = the schedule AND Paramount+. After consonant (목): 과.", "example_in_sentence": "방영 목록과 파라마운트+"}, {"type": "grammar", "label": "~에서 (from)", "exp": "Marks where something is removed from. 파라마운트+에서 삭제되었습니다 (was removed from Paramount+).", "example_in_sentence": "파라마운트+에서 삭제되었습니다"}, {"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "Past formal-polite ending. 삭제되다 → 삭제되었습니다 = was deleted (completed action).", "example_in_sentence": "삭제되었습니다"}]}, {"text": "삭제된 이유는 에피소드에 ''팬티 레이드'' 장면이 포함되어 있기 때문입니다.", "translation": "The reason for the removal is that the episode contains a ''panty raid'' scene.", "vocab": [{"ko": "이유", "en": "reason, cause", "note": ""}, {"ko": "장면", "en": "scene", "note": ""}, {"ko": "포함되다", "en": "to be included; to be contained", "note": ""}], "analysis": [{"type": "grammar", "label": "~에 (target of effect / location of content)", "exp": "Target or location marking where something exists/is contained. 에피소드에 포함되다 = contained IN the episode.", "example_in_sentence": "에피소드에 ''팬티 레이드'' 장면이 포함되어"}, {"type": "expression", "label": "~기 때문이다", "exp": "Gives the reason at the end of a sentence: ''it is because ~''. 포함되어 있다 → 포함되어 있기 때문입니다 (because it contains).", "example_in_sentence": "포함되어 있기 때문입니다"}]}, {"text": "''팬티 레이드''란 다른 사람의 속옷을 몰래 훔치는 장난을 가리키는 표현입니다.", "translation": "''Panty raid'' is an expression that refers to a prank of secretly stealing someone else''s underwear.", "vocab": [{"ko": "속옷", "en": "underwear, undergarments", "note": ""}, {"ko": "몰래", "en": "secretly, stealthily", "note": ""}, {"ko": "훔치다", "en": "steal, pilfer", "note": ""}, {"ko": "장난", "en": "prank, joke", "note": ""}], "analysis": [{"type": "grammar", "label": "~는 (present verb modifier)", "exp": "Lets an action describe a noun. 훔치다 → 훔치는 장난 (a prank of stealing).", "example_in_sentence": "훔치는 장난"}]}, {"text": "해당 장면이 어린이 대상 콘텐츠에 적합하지 않다고 판단되면서 방영이 중단된 것 같습니다.", "translation": "It seems the broadcast was stopped as the scene was judged unsuitable for content aimed at children.", "vocab": [{"ko": "해당", "en": "relevant, applicable, in question", "note": ""}, {"ko": "대상", "en": "target, subject, object", "note": ""}, {"ko": "콘텐츠", "en": "content", "note": ""}, {"ko": "적합하다", "en": "suitable, appropriate, fitting", "note": ""}], "analysis": [{"type": "grammar", "label": "~에 (target of effect)", "exp": "Target marking what something is good/bad/suitable for. 콘텐츠에 적합하다 = suitable FOR content.", "example_in_sentence": "콘텐츠에 적합하지 않다"}, {"type": "grammar", "label": "~(으)면서 (while / and at the same time / contrast)", "exp": "Simultaneous or contrastive action: 판단되면서 중단되다 = (it) was discontinued as (it) was being judged/while being judged.", "example_in_sentence": "판단되면서 방영이 중단된"}, {"type": "grammar", "label": "~다고 판단되다", "exp": "''Be judged that ~''. 적합하지 않다 → 적합하지 않다고 판단되면서 (as it was judged not suitable).", "example_in_sentence": "적합하지 않다고 판단되면서"}]}, {"text": "이 에피소드는 니켈로디언 채널과 스트리밍 플랫폼 파라마운트+ 모두에서 더 이상 볼 수 없게 되었습니다.", "translation": "This episode can no longer be seen on either Nickelodeon channel or streaming platform Paramount+.", "vocab": [{"ko": "채널", "en": "channel", "note": ""}, {"ko": "스트리밍", "en": "streaming", "note": ""}, {"ko": "플랫폼", "en": "platform", "note": ""}, {"ko": "모두", "en": "both, all", "note": ""}], "analysis": [{"type": "grammar", "label": "~과/와 (and — listing)", "exp": "Listing conjunction. 채널과 플랫폼 = channel AND platform. After consonant (널): 과.", "example_in_sentence": "채널과 스트리밍 플랫폼"}, {"type": "grammar", "label": "~에서 (action-location)", "exp": "Location where an action occurs (dynamic verb). 에서 볼 수 없다 = cannot be seen AT/ON (these platforms). Action-location, not static existence.", "example_in_sentence": "파라마운트+ 모두에서"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다/없다 (ability/possibility)", "exp": "Possibility/ability: negative form. 볼 수 없다 = cannot see. 보다 (see) → 볼 수 없다 (cannot be seen).", "example_in_sentence": "볼 수 없게 되었습니다"}, {"type": "grammar", "label": "~게 되다 (come to / passive)", "exp": "Become so; circumstantial change. 볼 수 없게 되다 = come to be unable to see / can no longer be seen.", "example_in_sentence": "볼 수 없게 되었습니다"}]}, {"text": "스펀지밥은 오랫동안 어린이 시청자를 대상으로 방영되어 온 시리즈이기 때문에, 이러한 결정이 내려진 것으로 보입니다.", "translation": "Because SpongeBob is a series that has been broadcast for a long time targeting child viewers, this decision appears to have been made.", "vocab": [{"ko": "오랫동안", "en": "for a long time", "note": ""}, {"ko": "시청자", "en": "viewer, audience", "note": ""}, {"ko": "대상", "en": "target, subject", "note": ""}, {"ko": "방영되다", "en": "to be broadcast; to air", "note": ""}], "analysis": [{"type": "grammar", "label": "~을/를 대상으로", "exp": "''Aimed at / targeting ~''. 어린이 시청자를 대상으로 (aimed at child viewers).", "example_in_sentence": "시청자를 대상으로"}, {"type": "grammar", "label": "~기 때문에", "exp": "''Because''. 시리즈이다 → 시리즈이기 때문에 (because it is a series).", "example_in_sentence": "시리즈이기 때문에"}]}], "version": "s6"}', vocab = '[{"ko": "애니메이션", "en": "animation", "note": ""}, {"ko": "시리즈", "en": "series", "note": ""}, {"ko": "에피소드", "en": "episode", "note": ""}, {"ko": "삭제되다", "en": "to be deleted; to be removed", "note": ""}, {"ko": "이유", "en": "reason, cause", "note": ""}, {"ko": "장면", "en": "scene", "note": ""}, {"ko": "포함되다", "en": "to be included; to be contained", "note": ""}, {"ko": "속옷", "en": "underwear, undergarments", "note": ""}, {"ko": "몰래", "en": "secretly, stealthily", "note": ""}, {"ko": "훔치다", "en": "steal, pilfer", "note": ""}, {"ko": "장난", "en": "prank, joke", "note": ""}, {"ko": "해당", "en": "relevant, applicable, in question", "note": ""}, {"ko": "대상", "en": "target, subject, object", "note": ""}, {"ko": "콘텐츠", "en": "content", "note": ""}, {"ko": "적합하다", "en": "suitable, appropriate, fitting", "note": ""}, {"ko": "채널", "en": "channel", "note": ""}, {"ko": "스트리밍", "en": "streaming", "note": ""}, {"ko": "플랫폼", "en": "platform", "note": ""}, {"ko": "모두", "en": "both, all", "note": ""}, {"ko": "오랫동안", "en": "for a long time", "note": ""}, {"ko": "시청자", "en": "viewer, audience", "note": ""}, {"ko": "방영되다", "en": "to be broadcast; to air", "note": ""}]', grammar = '{"patterns": [{"name": "~과/와 (and — listing)", "level": "Intermediate", "exp": "Listing conjunction connecting two nouns. 목록과 파라마운트+ = the schedule AND Paramount+. After consonant (목): 과.", "ex_ko": "애니메이션 시리즈 스펀지밥의 에피소드 ''중년의 위기''가 니켈로디언의 방영 목록과 파라마운트+에서 삭제되었습니다.", "ex_en": "The SpongeBob SquarePants animation episode ''Midlife Crisis'' has been removed from Nickelodeon''s broadcast schedule and Paramount+."}, {"name": "~에 (target of effect / location of content)", "level": "Intermediate", "exp": "Location where an action occurs (dynamic verb). 에서 볼 수 없다 = cannot be seen AT/ON (these platforms). Action-location, not static existence.", "ex_ko": "애니메이션 시리즈 스펀지밥의 에피소드 ''중년의 위기''가 니켈로디언의 방영 목록과 파라마운트+에서 삭제되었습니다.", "ex_en": "The SpongeBob SquarePants animation episode ''Midlife Crisis'' has been removed from Nickelodeon''s broadcast schedule and Paramount+."}, {"name": "~았/었/였습니다 (past formal)", "level": "Intermediate", "exp": "Past formal-polite ending. 삭제되다 → 삭제되었습니다 = was deleted (completed action).", "ex_ko": "애니메이션 시리즈 스펀지밥의 에피소드 ''중년의 위기''가 니켈로디언의 방영 목록과 파라마운트+에서 삭제되었습니다.", "ex_en": "The SpongeBob SquarePants animation episode ''Midlife Crisis'' has been removed from Nickelodeon''s broadcast schedule and Paramount+."}, {"name": "~는 (present verb modifier)", "level": "Intermediate", "exp": "Lets an action describe a noun. 훔치다 → 훔치는 장난 (a prank of stealing).", "ex_ko": "''팬티 레이드''란 다른 사람의 속옷을 몰래 훔치는 장난을 가리키는 표현입니다.", "ex_en": "''Panty raid'' is an expression that refers to a prank of secretly stealing someone else''s underwear."}, {"name": "~(으)면서 (while / and at the same time / contrast)", "level": "Intermediate", "exp": "Simultaneous or contrastive action: 판단되면서 중단되다 = (it) was discontinued as (it) was being judged/while being judged.", "ex_ko": "해당 장면이 어린이 대상 콘텐츠에 적합하지 않다고 판단되면서 방영이 중단된 것 같습니다.", "ex_en": "It seems the broadcast was stopped as the scene was judged unsuitable for content aimed at children."}, {"name": "~다고 판단되다", "level": "Intermediate", "exp": "''Be judged that ~''. 적합하지 않다 → 적합하지 않다고 판단되면서 (as it was judged not suitable).", "ex_ko": "해당 장면이 어린이 대상 콘텐츠에 적합하지 않다고 판단되면서 방영이 중단된 것 같습니다.", "ex_en": "It seems the broadcast was stopped as the scene was judged unsuitable for content aimed at children."}, {"name": "~(으)ㄹ 수 있다/없다 (ability/possibility)", "level": "Intermediate", "exp": "Possibility/ability: negative form. 볼 수 없다 = cannot see. 보다 (see) → 볼 수 없다 (cannot be seen).", "ex_ko": "이 에피소드는 니켈로디언 채널과 스트리밍 플랫폼 파라마운트+ 모두에서 더 이상 볼 수 없게 되었습니다.", "ex_en": "This episode can no longer be seen on either Nickelodeon channel or streaming platform Paramount+."}, {"name": "~게 되다 (come to / passive)", "level": "Intermediate", "exp": "Become so; circumstantial change. 볼 수 없게 되다 = come to be unable to see / can no longer be seen.", "ex_ko": "이 에피소드는 니켈로디언 채널과 스트리밍 플랫폼 파라마운트+ 모두에서 더 이상 볼 수 없게 되었습니다.", "ex_en": "This episode can no longer be seen on either Nickelodeon channel or streaming platform Paramount+."}, {"name": "~을/를 대상으로", "level": "Intermediate", "exp": "''Aimed at / targeting ~''. 어린이 시청자를 대상으로 (aimed at child viewers).", "ex_ko": "스펀지밥은 오랫동안 어린이 시청자를 대상으로 방영되어 온 시리즈이기 때문에, 이러한 결정이 내려진 것으로 보입니다.", "ex_en": "Because SpongeBob is a series that has been broadcast for a long time targeting child viewers, this decision appears to have been made."}, {"name": "~기 때문에", "level": "Intermediate", "exp": "''Because''. 시리즈이다 → 시리즈이기 때문에 (because it is a series).", "ex_ko": "스펀지밥은 오랫동안 어린이 시청자를 대상으로 방영되어 온 시리즈이기 때문에, 이러한 결정이 내려진 것으로 보입니다.", "ex_en": "Because SpongeBob is a series that has been broadcast for a long time targeting child viewers, this decision appears to have been made."}]}', updated_at = now() where article_id = 'mpjw73tjjnwq' and md5(translation) = '2274bf9599cf9ec650deca3cfaed730b';
update public.article_cache set translation = '{"texts": ["As the fact that cancer can develop cancer becomes known, it is receiving attention from the scientific community. This phenomenon is called ''super-tumor'' (or hypercancer).", "Super-tumor is the phenomenon of a new tumor developing on top of an existing tumor. In other words, cancer cells themselves become the host of another cancer.", "The reason super-tumor is receiving attention is because of the effect it has on existing tumors. Super-tumor plays the role of starving the original tumor to death by robbing it of nutrients.", "According to reports, if one uses such a principle, there is the possibility that super-tumor could be utilized in cancer treatment. This is because the method of attacking existing tumors by using super-tumor is theoretically possible."], "sentences": [{"text": "암이 암에 걸릴 수 있다는 사실이 알려지면서 과학계의 관심을 받고 있습니다.", "translation": "As the fact that cancer can develop cancer becomes known, it is receiving attention from the scientific community.", "vocab": [{"ko": "암", "en": "cancer", "note": ""}, {"ko": "걸리다", "en": "to contract; to develop (a disease)", "note": ""}, {"ko": "사실", "en": "fact", "note": ""}, {"ko": "알려지다", "en": "to become known", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다/없다 (ability/possibility)", "exp": "ability or possibility. 걸리다 → 걸릴 수 있다 = ''can contract''", "example_in_sentence": "걸릴 수 있다"}, {"type": "grammar", "label": "~(으)면서 (while / and at the same time / yet)", "exp": "SIMULTANEOUS use: two actions happening at the same time. 알려지다 + 받다 → 알려지면서 받고 있다 = ''as it becomes known, it is receiving''", "example_in_sentence": "알려지면서 받고 있습니다"}, {"type": "grammar", "label": "~고 있다 (continuous)", "exp": "progressive aspect. 받다 → 받고 있다 = ''is receiving (ongoing)''", "example_in_sentence": "받고 있습니다"}, {"type": "grammar", "label": "~다는 N", "exp": "Quotes a claim to describe a noun. 걸릴 수 있다 → 걸릴 수 있다는 사실 (the fact that it can get (cancer)).", "example_in_sentence": "걸릴 수 있다는 사실"}]}, {"text": "이 현상을 ''과종양''이라고 합니다.", "translation": "This phenomenon is called a ''hypertumor.''", "vocab": [{"ko": "현상", "en": "phenomenon", "note": ""}, {"ko": "과종양", "en": "hypertumor", "note": ""}], "analysis": []}, {"text": "과종양은 기존 종양 위에 새로운 종양이 생기는 현상입니다.", "translation": "A hypertumor is a phenomenon in which a new tumor forms on top of an existing tumor.", "vocab": [{"ko": "기존", "en": "existing; pre-existing", "note": ""}, {"ko": "종양", "en": "tumor", "note": ""}, {"ko": "새롭다", "en": "to be new", "note": ""}, {"ko": "생기다", "en": "to occur; to develop; to arise", "note": ""}], "analysis": []}, {"text": "즉, 암세포 자체가 또 다른 암의 숙주가 되는 것입니다.", "translation": "In other words, cancer cells themselves become the host of another cancer.", "vocab": [{"ko": "암세포", "en": "cancer cell", "note": ""}, {"ko": "자체", "en": "itself; the thing itself", "note": ""}, {"ko": "숙주", "en": "host", "note": ""}, {"ko": "되다", "en": "to become", "note": "core verb; listed as permitted"}], "analysis": []}, {"text": "과종양이 주목받는 이유는 기존 종양에 미치는 영향 때문입니다.", "translation": "The reason hypertumors are drawing attention is the effect they have on existing tumors.", "vocab": [{"ko": "주목받다", "en": "to receive attention; to be noticed", "note": ""}, {"ko": "이유", "en": "reason", "note": ""}, {"ko": "미치다", "en": "to have an effect on; to reach; to affect", "note": ""}, {"ko": "영향", "en": "effect; influence", "note": ""}], "analysis": []}, {"text": "과종양은 원래 종양의 영양분을 빼앗으면서 그 종양을 굶겨 죽이는 역할을 합니다.", "translation": "A hypertumor robs the original tumor of its nutrients and starves it to death.", "vocab": [{"ko": "원래", "en": "originally; the original", "note": ""}, {"ko": "영양분", "en": "nutrient", "note": ""}, {"ko": "빼앗다", "en": "to steal; to rob; to take away", "note": ""}, {"ko": "굶겨 죽이다", "en": "to starve to death", "note": "compound: 굶기다 (to starve) + 죽이다 (to kill)"}], "analysis": [{"type": "grammar", "label": "~(으)면서 (while / and at the same time / yet)", "exp": "SIMULTANEOUS use: two actions by the same subject happening at once. 빼앗다 + 죽이다 → 빼앗으면서 죽이다 = ''while robbing ... also kills''", "example_in_sentence": "빼앗으면서 죽이는"}]}, {"text": "이러한 원리를 이용하면 과종양이 암 치료에 활용될 가능성이 있다고 합니다.", "translation": "It is said that if this principle is used, hypertumors could possibly be used in cancer treatment.", "vocab": [{"ko": "원리", "en": "principle", "note": ""}, {"ko": "이용하다", "en": "to use; to utilize", "note": ""}, {"ko": "치료", "en": "treatment; therapy", "note": ""}, {"ko": "활용되다", "en": "to be utilized; to be put to use", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)면 (if / when / whenever)", "exp": "CONDITIONAL ''if'': hypothetical condition. 이용하다 → 이용하면 = ''if (one) uses''", "example_in_sentence": "이용하면"}]}, {"text": "과종양을 이용해 기존 종양을 공격하는 방식이 이론적으로 가능하기 때문입니다.", "translation": "This is because attacking existing tumors with hypertumors is theoretically possible.", "vocab": [{"ko": "공격하다", "en": "to attack", "note": ""}, {"ko": "방식", "en": "method; way; manner", "note": ""}, {"ko": "이론적", "en": "theoretical", "note": ""}, {"ko": "가능하다", "en": "to be possible", "note": ""}], "analysis": [{"type": "grammar", "label": "~적으로", "exp": "Adverb form of ~적 words: ''in a ~ way''. 이론 (theory) → 이론적 → 이론적으로 (theoretically).", "example_in_sentence": "이론적으로"}]}], "version": "s6"}', vocab = '[{"ko": "암", "en": "cancer", "note": ""}, {"ko": "걸리다", "en": "to contract; to develop (a disease)", "note": ""}, {"ko": "사실", "en": "fact", "note": ""}, {"ko": "알려지다", "en": "to become known", "note": ""}, {"ko": "현상", "en": "phenomenon", "note": ""}, {"ko": "과종양", "en": "hypertumor", "note": ""}, {"ko": "기존", "en": "existing; pre-existing", "note": ""}, {"ko": "종양", "en": "tumor", "note": ""}, {"ko": "새롭다", "en": "to be new", "note": ""}, {"ko": "생기다", "en": "to occur; to develop; to arise", "note": ""}, {"ko": "암세포", "en": "cancer cell", "note": ""}, {"ko": "자체", "en": "itself; the thing itself", "note": ""}, {"ko": "숙주", "en": "host", "note": ""}, {"ko": "되다", "en": "to become", "note": "core verb; listed as permitted"}, {"ko": "주목받다", "en": "to receive attention; to be noticed", "note": ""}, {"ko": "이유", "en": "reason", "note": ""}, {"ko": "미치다", "en": "to have an effect on; to reach; to affect", "note": ""}, {"ko": "영향", "en": "effect; influence", "note": ""}, {"ko": "원래", "en": "originally; the original", "note": ""}, {"ko": "영양분", "en": "nutrient", "note": ""}, {"ko": "빼앗다", "en": "to steal; to rob; to take away", "note": ""}, {"ko": "굶겨 죽이다", "en": "to starve to death", "note": "compound: 굶기다 (to starve) + 죽이다 (to kill)"}, {"ko": "원리", "en": "principle", "note": ""}, {"ko": "이용하다", "en": "to use; to utilize", "note": ""}, {"ko": "치료", "en": "treatment; therapy", "note": ""}, {"ko": "활용되다", "en": "to be utilized; to be put to use", "note": ""}, {"ko": "공격하다", "en": "to attack", "note": ""}, {"ko": "방식", "en": "method; way; manner", "note": ""}, {"ko": "이론적", "en": "theoretical", "note": ""}, {"ko": "가능하다", "en": "to be possible", "note": ""}]', grammar = '{"patterns": [{"name": "~(으)ㄹ 수 있다/없다 (ability/possibility)", "level": "Intermediate", "exp": "ability or possibility. 걸리다 → 걸릴 수 있다 = ''can contract''", "ex_ko": "암이 암에 걸릴 수 있다는 사실이 알려지면서 과학계의 관심을 받고 있습니다.", "ex_en": "As the fact that cancer can develop cancer becomes known, it is receiving attention from the scientific community."}, {"name": "~(으)면서 (while / and at the same time / yet)", "level": "Intermediate", "exp": "SIMULTANEOUS use: two actions by the same subject happening at once. 빼앗다 + 죽이다 → 빼앗으면서 죽이다 = ''while robbing ... also kills''", "ex_ko": "암이 암에 걸릴 수 있다는 사실이 알려지면서 과학계의 관심을 받고 있습니다.", "ex_en": "As the fact that cancer can develop cancer becomes known, it is receiving attention from the scientific community."}, {"name": "~고 있다 (continuous)", "level": "Intermediate", "exp": "progressive aspect. 받다 → 받고 있다 = ''is receiving (ongoing)''", "ex_ko": "암이 암에 걸릴 수 있다는 사실이 알려지면서 과학계의 관심을 받고 있습니다.", "ex_en": "As the fact that cancer can develop cancer becomes known, it is receiving attention from the scientific community."}, {"name": "~다는 N", "level": "Intermediate", "exp": "Quotes a claim to describe a noun. 걸릴 수 있다 → 걸릴 수 있다는 사실 (the fact that it can get (cancer)).", "ex_ko": "암이 암에 걸릴 수 있다는 사실이 알려지면서 과학계의 관심을 받고 있습니다.", "ex_en": "As the fact that cancer can develop cancer becomes known, it is receiving attention from the scientific community."}, {"name": "~적으로", "level": "Intermediate", "exp": "Adverb form of ~적 words: ''in a ~ way''. 이론 (theory) → 이론적 → 이론적으로 (theoretically).", "ex_ko": "과종양을 이용해 기존 종양을 공격하는 방식이 이론적으로 가능하기 때문입니다.", "ex_en": "This is because attacking existing tumors with hypertumors is theoretically possible."}]}', updated_at = now() where article_id = 'mpjw7edkt807' and md5(translation) = 'a6a2d89bab2e4a7f43ba0942363a8965';
update public.article_cache set translation = '{"texts": ["《Mechanical Pencil》 is a book that introduces engineering around us through illustrations. It explains how tools and machines in everyday life work through illustrations.", "This book''s title is Mechanical Pencil. Although a mechanical pencil looks small and simple, it contains precise engineering technology inside.", "Like a mechanical pencil, the book shows in detail things we usually just pass by. Through this book, readers can view tools in a new way.", "This book seems good for people who are interested in engineering. Because there are many illustrations, it is not difficult to understand."], "sentences": [{"text": "《Mechanical Pencil》은 우리 주변의 공학을 그림으로 소개하는 책이에요.", "translation": "《Mechanical Pencil》 is a book that introduces engineering around us through illustrations.", "vocab": [{"ko": "공학", "en": "engineering", "note": ""}, {"ko": "소개하다", "en": "to introduce", "note": ""}], "analysis": [{"type": "grammar", "label": "~는 (present verb modifier)", "exp": "Present participle forming a relative clause. 소개하다 → 소개하는 (the book that introduces).", "example_in_sentence": "소개하는 책"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "Direct object particle. 공학을 소개하다 (introduce engineering).", "example_in_sentence": "공학을"}, {"type": "grammar", "label": "~은/는 (topic marker)", "exp": "Topic particle marking the subject of the sentence.", "example_in_sentence": "Mechanical Pencil》은"}, {"type": "grammar", "label": "~(으)로 (means / direction / transformation)", "exp": "Instrument/method marker. 그림으로 소개하다 (introduce by means of illustrations).", "example_in_sentence": "그림으로"}, {"type": "grammar", "label": "~의 (possessive / relational)", "exp": "Genitive/relational marker. 우리 주변의 공학 (engineering of/around us).", "example_in_sentence": "우리 주변의"}]}, {"text": "일상 속 도구와 기계가 어떻게 작동하는지 그림으로 설명해요.", "translation": "It explains how tools and machines in everyday life work through illustrations.", "vocab": [{"ko": "일상", "en": "daily life; everyday", "note": ""}, {"ko": "도구", "en": "tool", "note": ""}, {"ko": "기계", "en": "machine", "note": ""}, {"ko": "작동하다", "en": "to operate; to work", "note": ""}], "analysis": [{"type": "grammar", "label": "~아/어/여요 (present polite — contracted)", "exp": "Contracted polite present ending. 설명하다 → 설명해요 (explains).", "example_in_sentence": "설명해요"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle marking the agent of the action.", "example_in_sentence": "도구와 기계가"}, {"type": "grammar", "label": "~(으)로 (means / direction / transformation)", "exp": "Instrument marker. 그림으로 설명하다 (explain by means of illustrations).", "example_in_sentence": "그림으로"}, {"type": "grammar", "label": "~과/와 (with — comitative / and — listing)", "exp": "Listing conjunction (and). 도구와 기계 (tools and machines).", "example_in_sentence": "도구와 기계"}, {"type": "expression", "label": "~는지 (embedded question)", "exp": "Puts a question inside a sentence: ''how / whether ~''. 작동하다 → 어떻게 작동하는지 (how it works).", "example_in_sentence": "어떻게 작동하는지"}]}, {"text": "이 책의 제목은 샤프펜슬이에요.", "translation": "This book''s title is Mechanical Pencil.", "vocab": [{"ko": "제목", "en": "title", "note": ""}], "analysis": [{"type": "grammar", "label": "~은/는 (topic marker)", "exp": "Topic particle marking the subject.", "example_in_sentence": "제목은"}, {"type": "grammar", "label": "~의 (possessive / relational)", "exp": "Genitive marker showing possession. 책의 제목 (the title of the book).", "example_in_sentence": "책의"}]}, {"text": "샤프펜슬은 작고 간단해 보이지만, 그 안에 정밀한 공학 기술이 있어요.", "translation": "Although a mechanical pencil looks small and simple, it contains precise engineering technology inside.", "vocab": [{"ko": "작다", "en": "small; little", "note": ""}, {"ko": "간단하다", "en": "simple; easy", "note": ""}, {"ko": "보이다", "en": "to appear; to look", "note": ""}, {"ko": "정밀하다", "en": "precise; exact", "note": ""}], "analysis": [{"type": "grammar", "label": "~은/는 (topic marker)", "exp": "Topic particle marking the subject.", "example_in_sentence": "샤프펜슬은"}, {"type": "grammar", "label": "~지만 (but)", "exp": "Contrast connective. 보이지만 (but it looks / although it appears).", "example_in_sentence": "보이지만"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle marking the theme.", "example_in_sentence": "기술이"}, {"type": "grammar", "label": "~에 (location / time / direction / target)", "exp": "Static location marker. 안에 (inside).", "example_in_sentence": "안에"}, {"type": "expression", "label": "~아/어 보이다 (to appear / to look)", "exp": "Expression meaning appearance or seeming. 작고 간단해 보이다 (looks small and simple).", "example_in_sentence": "작고 간단해 보이지만"}]}, {"text": "책은 샤프펜슬처럼 평소에 그냥 지나치는 것들을 자세히 보여 줘요.", "translation": "Like a mechanical pencil, the book shows in detail things we usually just pass by.", "vocab": [{"ko": "평소", "en": "usually; normally; ordinarily", "note": ""}, {"ko": "지나치다", "en": "to pass by; to go past; to overlook", "note": ""}, {"ko": "자세히", "en": "in detail; carefully", "note": ""}, {"ko": "보여 주다", "en": "to show", "note": ""}], "analysis": [{"type": "grammar", "label": "~은/는 (topic marker)", "exp": "Topic particle marking the subject.", "example_in_sentence": "책은"}, {"type": "grammar", "label": "~는 (present verb modifier)", "exp": "Lets an action describe a noun. 지나치다 → 지나치는 것들 (things we pass by).", "example_in_sentence": "지나치는"}, {"type": "grammar", "label": "~히 (adverb suffix, Sino-Korean)", "exp": "Adverbializer for adjectives. 자세하다 → 자세히 (in detail; carefully).", "example_in_sentence": "자세히"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "Direct object particle. 것들을 보이다 (show things).", "example_in_sentence": "것들을"}, {"type": "grammar", "label": "~에 (location / time / direction / target)", "exp": "Time/frequency location. 평소에 (at ordinary times; usually).", "example_in_sentence": "평소에"}, {"type": "expression", "label": "~처럼 (like; as; similar to)", "exp": "Similitude marker. 샤프펜슬처럼 (like a mechanical pencil).", "example_in_sentence": "샤프펜슬처럼"}, {"type": "expression", "label": "보여주다 (to show)", "exp": "Combination of 보이다 (show) + 주다 (give). 자세히 보여줘요 (shows in detail).", "example_in_sentence": "보여 줘요"}]}, {"text": "독자는 이 책을 통해 도구를 새롭게 볼 수 있어요.", "translation": "Through this book, readers can view tools in a new way.", "vocab": [{"ko": "독자", "en": "reader", "note": ""}, {"ko": "도구", "en": "tool", "note": ""}, {"ko": "새롭다", "en": "new; fresh", "note": ""}, {"ko": "보다", "en": "to see; to look; to view", "note": ""}], "analysis": [{"type": "grammar", "label": "~은/는 (topic marker)", "exp": "Topic particle marking the subject.", "example_in_sentence": "독자는"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "Direct object particle. 도구를 보다 (view tools).", "example_in_sentence": "도구를"}, {"type": "grammar", "label": "~(으)ㄹ 수 있다/없다 (ability/possibility)", "exp": "Ability/possibility marker. 볼 수 있어요 (can see / are able to view).", "example_in_sentence": "볼 수 있어요"}, {"type": "grammar", "label": "~게 (adverbializer suffix)", "exp": "Adverbializer for adjectives. 새롭다 → 새롭게 (newly; in a new manner).", "example_in_sentence": "새롭게"}, {"type": "grammar", "label": "~아/어/여요 (present polite)", "exp": "Polite present ending. 있다 → 있어요 (are able).", "example_in_sentence": "있어요"}, {"type": "expression", "label": "~을/를 통해 (through)", "exp": "Medium/channel marker. 책을 통해 (through the book; by means of the book).", "example_in_sentence": "책을 통해"}]}, {"text": "이 책은 공학에 관심이 있는 사람들에게 좋을 것 같아요.", "translation": "This book seems good for people who are interested in engineering.", "vocab": [{"ko": "공학", "en": "engineering", "note": ""}, {"ko": "관심", "en": "interest", "note": ""}, {"ko": "있다", "en": "to exist; to have", "note": ""}, {"ko": "사람", "en": "person", "note": ""}], "analysis": [{"type": "grammar", "label": "~은/는 (topic marker)", "exp": "Topic particle marking the subject.", "example_in_sentence": "책은"}, {"type": "grammar", "label": "~는 (verb modifier)", "exp": "Lets a verb describe a noun. 있다 → 있는; 관심이 있는 사람들 (people who are interested).", "example_in_sentence": "있는"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle marking the existence of interest.", "example_in_sentence": "관심이"}, {"type": "grammar", "label": "~에게/한테 (to person)", "exp": "Indirect object for animate recipient. 사람들에게 좋다 (is good for people).", "example_in_sentence": "사람들에게"}, {"type": "grammar", "label": "~에 (location / time / direction / target)", "exp": "Target of effect marker. 공학에 관심이 있다 (have interest in engineering).", "example_in_sentence": "공학에"}, {"type": "expression", "label": "~ㄴ/는/을 것 같다 (seems)", "exp": "Conjecture/supposition. 좋을 것 같아요 (seems like it would be good).", "example_in_sentence": "좋을 것 같아요"}]}, {"text": "그림이 많기 때문에 이해하기도 어렵지 않아요.", "translation": "Because there are many illustrations, it is not difficult to understand.", "vocab": [{"ko": "그림", "en": "picture; illustration", "note": ""}, {"ko": "많다", "en": "many; much; abundant", "note": ""}, {"ko": "이해하다", "en": "to understand; to comprehend", "note": ""}, {"ko": "어렵다", "en": "difficult; hard", "note": ""}], "analysis": [{"type": "grammar", "label": "~이/가 (subject marker)", "exp": "Subject particle. 그림이 많다 (there are many pictures).", "example_in_sentence": "그림이"}, {"type": "grammar", "label": "~기 때문에 (because)", "exp": "Causal/reason conjunction. 많기 때문에 (because of being many).", "example_in_sentence": "많기 때문에"}, {"type": "grammar", "label": "~지 않다 (negation)", "exp": "Long-form negation. 어렵다 → 어렵지 않다 (is not difficult).", "example_in_sentence": "어렵지 않아요"}, {"type": "grammar", "label": "~아/어/여요 (present polite)", "exp": "Polite present ending. 않다 → 않아요 (is not).", "example_in_sentence": "어렵지 않아요"}, {"type": "grammar", "label": "~도 (also / even)", "exp": "Additive particle (also). 이해하기도 어렵지 않다 (understanding is also not difficult).", "example_in_sentence": "이해하기도"}, {"type": "expression", "label": "~기 (nominalizer)", "exp": "Turns a verb into a noun: ''to ~ / ~ing''. 이해하다 → 이해하기 (understanding).", "example_in_sentence": "이해하기도"}]}], "version": "s6"}', vocab = '[{"ko": "공학", "en": "engineering", "note": ""}, {"ko": "소개하다", "en": "to introduce", "note": ""}, {"ko": "일상", "en": "daily life; everyday", "note": ""}, {"ko": "도구", "en": "tool", "note": ""}, {"ko": "기계", "en": "machine", "note": ""}, {"ko": "작동하다", "en": "to operate; to work", "note": ""}, {"ko": "제목", "en": "title", "note": ""}, {"ko": "작다", "en": "small; little", "note": ""}, {"ko": "간단하다", "en": "simple; easy", "note": ""}, {"ko": "보이다", "en": "to appear; to look", "note": ""}, {"ko": "정밀하다", "en": "precise; exact", "note": ""}, {"ko": "평소", "en": "usually; normally; ordinarily", "note": ""}, {"ko": "지나치다", "en": "to pass by; to go past; to overlook", "note": ""}, {"ko": "자세히", "en": "in detail; carefully", "note": ""}, {"ko": "보여 주다", "en": "to show", "note": ""}, {"ko": "독자", "en": "reader", "note": ""}, {"ko": "새롭다", "en": "new; fresh", "note": ""}, {"ko": "보다", "en": "to see; to look; to view", "note": ""}, {"ko": "관심", "en": "interest", "note": ""}, {"ko": "있다", "en": "to exist; to have", "note": ""}, {"ko": "사람", "en": "person", "note": ""}, {"ko": "그림", "en": "picture; illustration", "note": ""}, {"ko": "많다", "en": "many; much; abundant", "note": ""}, {"ko": "이해하다", "en": "to understand; to comprehend", "note": ""}, {"ko": "어렵다", "en": "difficult; hard", "note": ""}]', grammar = '{"patterns": [{"name": "~는 (present verb modifier)", "level": "Beginner", "exp": "Present participle forming a relative clause. 소개하다 → 소개하는 (the book that introduces).", "ex_ko": "《Mechanical Pencil》은 우리 주변의 공학을 그림으로 소개하는 책이에요.", "ex_en": "《Mechanical Pencil》 is a book that introduces engineering around us through illustrations."}, {"name": "~을/를 (object marker)", "level": "Beginner", "exp": "Direct object particle. 공학을 소개하다 (introduce engineering).", "ex_ko": "《Mechanical Pencil》은 우리 주변의 공학을 그림으로 소개하는 책이에요.", "ex_en": "《Mechanical Pencil》 is a book that introduces engineering around us through illustrations."}, {"name": "~은/는 (topic marker)", "level": "Beginner", "exp": "Topic particle marking the subject of the sentence.", "ex_ko": "《Mechanical Pencil》은 우리 주변의 공학을 그림으로 소개하는 책이에요.", "ex_en": "《Mechanical Pencil》 is a book that introduces engineering around us through illustrations."}, {"name": "~(으)로 (means / direction / transformation)", "level": "Beginner", "exp": "Instrument/method marker. 그림으로 소개하다 (introduce by means of illustrations).", "ex_ko": "《Mechanical Pencil》은 우리 주변의 공학을 그림으로 소개하는 책이에요.", "ex_en": "《Mechanical Pencil》 is a book that introduces engineering around us through illustrations."}, {"name": "~의 (possessive / relational)", "level": "Beginner", "exp": "Genitive marker showing possession. 책의 제목 (the title of the book).", "ex_ko": "《Mechanical Pencil》은 우리 주변의 공학을 그림으로 소개하는 책이에요.", "ex_en": "《Mechanical Pencil》 is a book that introduces engineering around us through illustrations."}, {"name": "~아/어/여요 (present polite — contracted)", "level": "Beginner", "exp": "Contracted polite present ending. 설명하다 → 설명해요 (explains).", "ex_ko": "일상 속 도구와 기계가 어떻게 작동하는지 그림으로 설명해요.", "ex_en": "It explains how tools and machines in everyday life work through illustrations."}, {"name": "~이/가 (subject marker)", "level": "Beginner", "exp": "Subject particle marking the existence of interest.", "ex_ko": "일상 속 도구와 기계가 어떻게 작동하는지 그림으로 설명해요.", "ex_en": "It explains how tools and machines in everyday life work through illustrations."}, {"name": "~과/와 (with — comitative / and — listing)", "level": "Beginner", "exp": "Listing conjunction (and). 도구와 기계 (tools and machines).", "ex_ko": "일상 속 도구와 기계가 어떻게 작동하는지 그림으로 설명해요.", "ex_en": "It explains how tools and machines in everyday life work through illustrations."}, {"name": "~지만 (but)", "level": "Beginner", "exp": "Contrast connective. 보이지만 (but it looks / although it appears).", "ex_ko": "샤프펜슬은 작고 간단해 보이지만, 그 안에 정밀한 공학 기술이 있어요.", "ex_en": "Although a mechanical pencil looks small and simple, it contains precise engineering technology inside."}, {"name": "~에 (location / time / direction / target)", "level": "Beginner", "exp": "Target of effect marker. 공학에 관심이 있다 (have interest in engineering).", "ex_ko": "샤프펜슬은 작고 간단해 보이지만, 그 안에 정밀한 공학 기술이 있어요.", "ex_en": "Although a mechanical pencil looks small and simple, it contains precise engineering technology inside."}, {"name": "~히 (adverb suffix, Sino-Korean)", "level": "Beginner", "exp": "Adverbializer for adjectives. 자세하다 → 자세히 (in detail; carefully).", "ex_ko": "책은 샤프펜슬처럼 평소에 그냥 지나치는 것들을 자세히 보여 줘요.", "ex_en": "Like a mechanical pencil, the book shows in detail things we usually just pass by."}, {"name": "~(으)ㄹ 수 있다/없다 (ability/possibility)", "level": "Beginner", "exp": "Ability/possibility marker. 볼 수 있어요 (can see / are able to view).", "ex_ko": "독자는 이 책을 통해 도구를 새롭게 볼 수 있어요.", "ex_en": "Through this book, readers can view tools in a new way."}, {"name": "~게 (adverbializer suffix)", "level": "Beginner", "exp": "Adverbializer for adjectives. 새롭다 → 새롭게 (newly; in a new manner).", "ex_ko": "독자는 이 책을 통해 도구를 새롭게 볼 수 있어요.", "ex_en": "Through this book, readers can view tools in a new way."}, {"name": "~에게/한테 (to person)", "level": "Beginner", "exp": "Indirect object for animate recipient. 사람들에게 좋다 (is good for people).", "ex_ko": "이 책은 공학에 관심이 있는 사람들에게 좋을 것 같아요.", "ex_en": "This book seems good for people who are interested in engineering."}, {"name": "~기 때문에 (because)", "level": "Beginner", "exp": "Causal/reason conjunction. 많기 때문에 (because of being many).", "ex_ko": "그림이 많기 때문에 이해하기도 어렵지 않아요.", "ex_en": "Because there are many illustrations, it is not difficult to understand."}]}', updated_at = now() where article_id = 'mptuh0ukz9bz' and md5(translation) = 'f96fefefe610d9292ffdd0743fd029ca';
update public.article_cache set translation = '{"texts": ["Actor Robert Pattinson is becoming a hot topic by making an honest confession about his life after the film ''The Batman''. He revealed that he could not find large-scale works of similar magnitude after ''Batman''.", "Pattinson came to receive worldwide attention thanks to ''The Batman''. However, it is said that finding works of the same scale after that was not easy.", "It is not rare for cases to arise where it becomes difficult to seize similar opportunities after appearing in a major franchise. Pattinson likewise seems to have directly experienced such a situation.", "This confession is receiving considerable attention in the respect that it demonstrates the difficulties that Hollywood actors face after appearing in blockbusters."], "sentences": [{"text": "배우 로버트 패티슨이 영화 ''더 배트맨'' 이후의 삶에 대해 솔직한 고백을 해서 화제가 되고 있습니다.", "translation": "Actor Robert Pattinson is becoming a hot topic by making an honest confession about his life after the film ''The Batman''.", "vocab": [{"ko": "배우", "en": "actor", "note": ""}, {"ko": "이후", "en": "after", "note": ""}, {"ko": "고백", "en": "confession", "note": ""}, {"ko": "화제", "en": "hot topic / subject of conversation", "note": ""}], "analysis": [{"type": "grammar", "label": "~고 있다 (continuous)", "exp": "Progressive aspect indicating an ongoing state. 되다 → 되고 있다 (is becoming / is happening). Speaker describes a process in progress.", "example_in_sentence": "화제가 되고 있습니다"}, {"type": "grammar", "label": "~아/어서 (cause / sequence)", "exp": "Causal or sequential connector. 하다 → 해서 (because of doing / and then doing). The confession causes the topic status.", "example_in_sentence": "고백을 해서"}, {"type": "grammar", "label": "~에 대해(서)/대한 (about)", "exp": "Topical marker meaning ''about/regarding''. Shows the target or subject of the confession.", "example_in_sentence": "삶에 대해"}]}, {"text": "그는 ''배트맨'' 이후에 비슷한 규모의 대형 작품을 찾지 못했다고 밝혔습니다.", "translation": "He revealed that he could not find large-scale works of similar magnitude after ''Batman''.", "vocab": [{"ko": "규모", "en": "scale / magnitude", "note": ""}, {"ko": "대형", "en": "large-scale / major", "note": ""}, {"ko": "작품", "en": "work (film/art)", "note": ""}, {"ko": "밝히다", "en": "reveal / state / announce", "note": ""}], "analysis": [{"type": "grammar", "label": "~지 못하다", "exp": "Long-form inability marker. 찾다 → 찾지 못하다 (could not find / was unable to find).", "example_in_sentence": "찾지 못했다"}, {"type": "grammar", "label": "~다고 밝히다", "exp": "Reports a statement: ''reveal / state that ~''. 찾지 못했다 → 찾지 못했다고 밝혔습니다 (revealed that he could not find).", "example_in_sentence": "찾지 못했다고 밝혔습니다"}]}, {"text": "패티슨은 ''더 배트맨''으로 전 세계적인 주목을 받게 되었습니다.", "translation": "Pattinson came to receive worldwide attention thanks to ''The Batman''.", "vocab": [{"ko": "주목", "en": "attention / spotlight (focused)", "note": "stronger/more formal than 관심"}, {"ko": "세계", "en": "world", "note": ""}], "analysis": [{"type": "grammar", "label": "~게 되다 (come to / passive)", "exp": "Expressing circumstantial change or passive resultative. 받게 되었다 = ''came to receive / ended up receiving''.", "example_in_sentence": "받게 되었습니다"}, {"type": "grammar", "label": "~적 (-ic / -al adjective suffix)", "exp": "Sino-Korean adjective suffix. 세계 (world) + 적 = 세계적 (worldwide / international). Modifies 주목 as ''세계적인 주목'' (worldwide attention).", "example_in_sentence": "세계적인"}, {"type": "grammar", "label": "~(으)로 (means / direction / transformation)", "exp": "Instrumental/means marker. ''더 배트맨으로 = by means of / through ''The Batman''.", "example_in_sentence": "배트맨으로"}, {"type": "expression", "label": "주목을 받다", "exp": "Collocation: ''receive attention''. 주목을 받게 되었습니다 (came to receive attention).", "example_in_sentence": "주목을 받게 되었습니다"}]}, {"text": "하지만 그 이후에 같은 규모의 작품을 찾는 것이 쉽지 않았다고 합니다.", "translation": "However, it is said that finding works of the same scale after that was not easy.", "vocab": [{"ko": "규모", "en": "scale / magnitude", "note": ""}, {"ko": "작품", "en": "work (film/art)", "note": ""}], "analysis": [{"type": "grammar", "label": "~지 않다", "exp": "Long-form negation. 쉽다 → 쉽지 않다 (is not easy / is difficult). More formal/emphatic than short negation.", "example_in_sentence": "쉽지 않았다"}, {"type": "expression", "label": "~는 것이 쉽지 않다", "exp": "''Doing ~ is not easy''. 찾다 → 찾는 것이 쉽지 않았다 (finding was not easy).", "example_in_sentence": "찾는 것이 쉽지 않았다"}]}, {"text": "대형 프랜차이즈에 출연한 후에 비슷한 기회를 잡기 어려워지는 경우는 드문 일이 아닙니다.", "translation": "It is not unusual for it to become harder to get similar opportunities after appearing in a major franchise.", "vocab": [{"ko": "프랜차이즈", "en": "franchise (film series)", "note": ""}, {"ko": "출연하다", "en": "appear in / star in", "note": ""}, {"ko": "기회", "en": "opportunity / chance", "note": ""}, {"ko": "잡다", "en": "seize / grasp / catch", "note": ""}], "analysis": [{"type": "grammar", "label": "~기 어려워지다", "exp": "''Become hard to do''. 어렵다 → 어려워지다 (become hard); 잡기 어려워지는 (becoming hard to get).", "example_in_sentence": "잡기 어려워지는"}, {"type": "expression", "label": "기회를 잡다", "exp": "Collocation: ''seize / get an opportunity''.", "example_in_sentence": "기회를 잡기"}]}, {"text": "패티슨 역시 그런 상황을 직접 경험한 것 같습니다.", "translation": "Pattinson likewise seems to have directly experienced such a situation.", "vocab": [{"ko": "역시", "en": "likewise / also / as expected", "note": ""}, {"ko": "상황", "en": "situation / circumstance", "note": ""}, {"ko": "경험하다", "en": "experience", "note": ""}], "analysis": [{"type": "expression", "label": "~(으)ㄴ 것 같다", "exp": "A guess about the past: ''seems to have ~ed''. 경험하다 → 경험한 것 같습니다 (seems to have experienced).", "example_in_sentence": "경험한 것 같습니다"}]}, {"text": "이번 고백은 할리우드 배우들이 블록버스터 출연 이후 겪는 어려움을 보여 준다는 점에서 많은 관심을 받고 있습니다.", "translation": "This confession is drawing a lot of attention because it shows the difficulties Hollywood actors face after appearing in blockbusters.", "vocab": [{"ko": "고백", "en": "confession", "note": ""}, {"ko": "할리우드", "en": "Hollywood", "note": ""}, {"ko": "블록버스터", "en": "blockbuster", "note": ""}, {"ko": "출연하다", "en": "appear in / star in", "note": ""}], "analysis": [{"type": "grammar", "label": "~ㄴ/는다는 점에서", "exp": "''In that ~ / in the sense that ~''. 보여 주다 → 보여 준다는 점에서 (in that it shows).", "example_in_sentence": "보여 준다는 점에서"}, {"type": "grammar", "label": "~고 있다 (continuous)", "exp": "Progressive aspect. 받고 있습니다 = ''is receiving / is gaining (attention)''.", "example_in_sentence": "받고 있습니다"}, {"type": "expression", "label": "관심을 받다", "exp": "Collocation: ''receive attention / interest''. 관심을 받고 있습니다 (is receiving attention).", "example_in_sentence": "관심을 받고"}]}], "version": "s6"}', vocab = '[{"ko": "배우", "en": "actor", "note": ""}, {"ko": "이후", "en": "after", "note": ""}, {"ko": "고백", "en": "confession", "note": ""}, {"ko": "화제", "en": "hot topic / subject of conversation", "note": ""}, {"ko": "규모", "en": "scale / magnitude", "note": ""}, {"ko": "대형", "en": "large-scale / major", "note": ""}, {"ko": "작품", "en": "work (film/art)", "note": ""}, {"ko": "밝히다", "en": "reveal / state / announce", "note": ""}, {"ko": "주목", "en": "attention / spotlight (focused)", "note": "stronger/more formal than 관심"}, {"ko": "세계", "en": "world", "note": ""}, {"ko": "프랜차이즈", "en": "franchise (film series)", "note": ""}, {"ko": "출연하다", "en": "appear in / star in", "note": ""}, {"ko": "기회", "en": "opportunity / chance", "note": ""}, {"ko": "잡다", "en": "seize / grasp / catch", "note": ""}, {"ko": "역시", "en": "likewise / also / as expected", "note": ""}, {"ko": "상황", "en": "situation / circumstance", "note": ""}, {"ko": "경험하다", "en": "experience", "note": ""}, {"ko": "할리우드", "en": "Hollywood", "note": ""}, {"ko": "블록버스터", "en": "blockbuster", "note": ""}]', grammar = '{"patterns": [{"name": "~고 있다 (continuous)", "level": "Intermediate", "exp": "Progressive aspect indicating an ongoing state. 되다 → 되고 있다 (is becoming / is happening). Speaker describes a process in progress.", "ex_ko": "배우 로버트 패티슨이 영화 ''더 배트맨'' 이후의 삶에 대해 솔직한 고백을 해서 화제가 되고 있습니다.", "ex_en": "Actor Robert Pattinson is becoming a hot topic by making an honest confession about his life after the film ''The Batman''."}, {"name": "~아/어서 (cause / sequence)", "level": "Intermediate", "exp": "Causal or sequential connector. 하다 → 해서 (because of doing / and then doing). The confession causes the topic status.", "ex_ko": "배우 로버트 패티슨이 영화 ''더 배트맨'' 이후의 삶에 대해 솔직한 고백을 해서 화제가 되고 있습니다.", "ex_en": "Actor Robert Pattinson is becoming a hot topic by making an honest confession about his life after the film ''The Batman''."}, {"name": "~에 대해(서)/대한 (about)", "level": "Intermediate", "exp": "Topical marker meaning ''about/regarding''. Shows the target or subject of the confession.", "ex_ko": "배우 로버트 패티슨이 영화 ''더 배트맨'' 이후의 삶에 대해 솔직한 고백을 해서 화제가 되고 있습니다.", "ex_en": "Actor Robert Pattinson is becoming a hot topic by making an honest confession about his life after the film ''The Batman''."}, {"name": "~지 못하다", "level": "Intermediate", "exp": "Long-form inability marker. 찾다 → 찾지 못하다 (could not find / was unable to find).", "ex_ko": "그는 ''배트맨'' 이후에 비슷한 규모의 대형 작품을 찾지 못했다고 밝혔습니다.", "ex_en": "He revealed that he could not find large-scale works of similar magnitude after ''Batman''."}, {"name": "~다고 밝히다", "level": "Intermediate", "exp": "Reports a statement: ''reveal / state that ~''. 찾지 못했다 → 찾지 못했다고 밝혔습니다 (revealed that he could not find).", "ex_ko": "그는 ''배트맨'' 이후에 비슷한 규모의 대형 작품을 찾지 못했다고 밝혔습니다.", "ex_en": "He revealed that he could not find large-scale works of similar magnitude after ''Batman''."}, {"name": "~게 되다 (come to / passive)", "level": "Intermediate", "exp": "Expressing circumstantial change or passive resultative. 받게 되었다 = ''came to receive / ended up receiving''.", "ex_ko": "패티슨은 ''더 배트맨''으로 전 세계적인 주목을 받게 되었습니다.", "ex_en": "Pattinson came to receive worldwide attention thanks to ''The Batman''."}, {"name": "~적 (-ic / -al adjective suffix)", "level": "Intermediate", "exp": "Sino-Korean adjective suffix. 세계 (world) + 적 = 세계적 (worldwide / international). Modifies 주목 as ''세계적인 주목'' (worldwide attention).", "ex_ko": "패티슨은 ''더 배트맨''으로 전 세계적인 주목을 받게 되었습니다.", "ex_en": "Pattinson came to receive worldwide attention thanks to ''The Batman''."}, {"name": "~(으)로 (means / direction / transformation)", "level": "Intermediate", "exp": "Instrumental/means marker. ''더 배트맨으로 = by means of / through ''The Batman''.", "ex_ko": "패티슨은 ''더 배트맨''으로 전 세계적인 주목을 받게 되었습니다.", "ex_en": "Pattinson came to receive worldwide attention thanks to ''The Batman''."}, {"name": "~지 않다", "level": "Intermediate", "exp": "Long-form negation. 쉽다 → 쉽지 않다 (is not easy / is difficult). More formal/emphatic than short negation.", "ex_ko": "하지만 그 이후에 같은 규모의 작품을 찾는 것이 쉽지 않았다고 합니다.", "ex_en": "However, it is said that finding works of the same scale after that was not easy."}, {"name": "~기 어려워지다", "level": "Intermediate", "exp": "''Become hard to do''. 어렵다 → 어려워지다 (become hard); 잡기 어려워지는 (becoming hard to get).", "ex_ko": "대형 프랜차이즈에 출연한 후에 비슷한 기회를 잡기 어려워지는 경우는 드문 일이 아닙니다.", "ex_en": "It is not unusual for it to become harder to get similar opportunities after appearing in a major franchise."}, {"name": "~ㄴ/는다는 점에서", "level": "Intermediate", "exp": "''In that ~ / in the sense that ~''. 보여 주다 → 보여 준다는 점에서 (in that it shows).", "ex_ko": "이번 고백은 할리우드 배우들이 블록버스터 출연 이후 겪는 어려움을 보여 준다는 점에서 많은 관심을 받고 있습니다.", "ex_en": "This confession is drawing a lot of attention because it shows the difficulties Hollywood actors face after appearing in blockbusters."}]}', updated_at = now() where article_id = 'mpwr432i00v4' and md5(translation) = 'e22880d3b1cd1cbbda81af9c3a70c977';
update public.article_cache set translation = '{"texts": ["The technology that enables robots to sense their surroundings has greatly advanced. Robots can now sense reality just like humans do.", "In the past, robots could only perform simple movements. However, now it has become possible to recognize the surrounding situation.", "By utilizing new technology, robots'' sensory abilities have increased. Robots can now touch objects or detect environmental changes.", "This technology can be used in various fields in the future. Robot technology continues to develop."], "sentences": [{"text": "로봇이 주변 환경을 느끼는 기술이 크게 발전했어요.", "translation": "The technology that enables robots to sense their surroundings has greatly advanced.", "vocab": [{"ko": "로봇", "en": "robot", "note": ""}, {"ko": "주변", "en": "surroundings / vicinity", "note": ""}, {"ko": "환경", "en": "environment", "note": ""}, {"ko": "느끼다", "en": "to feel / to sense", "note": ""}], "analysis": [{"type": "grammar", "label": "~게 (adverb ending)", "exp": "Turns an adjective into an adverb. 크다 (big) → 크게 (greatly).", "example_in_sentence": "크게"}, {"type": "grammar", "label": "~았/었/였어요 (past polite)", "exp": "Past polite with vowel contraction. 발전하다 → 발전했어요.", "example_in_sentence": "발전했어요"}]}, {"text": "로봇은 이제 인간처럼 현실을 감지할 수 있어요.", "translation": "Robots can now sense reality just like humans do.", "vocab": [{"ko": "인간", "en": "human / human being", "note": ""}, {"ko": "현실", "en": "reality", "note": ""}, {"ko": "감지하다", "en": "to sense / to detect", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다/없다 (ability/possibility)", "exp": "Can/ability. 감지할 수 있다 (can sense).", "example_in_sentence": "감지할 수 있어요"}]}, {"text": "예전에는 로봇이 단순한 동작만 할 수 있었어요.", "translation": "In the past, robots could only perform simple movements.", "vocab": [{"ko": "예전", "en": "long ago / the past", "note": ""}, {"ko": "단순하다", "en": "to be simple", "note": ""}, {"ko": "동작", "en": "movement / motion / action", "note": ""}], "analysis":