update public.article_cache set translation = '{"texts": ["Vinyl bags have become scarce in Japan.", "It has become difficult to find vinyl bags at supermarkets and bakeries. Vinyl gloves used in food shops have also become scarce.", "Vinyl bags are made from naphtha. The Middle East is Japan''s most important crude oil supply source.", "Due to the Iran war, naphtha has become scarce. Therefore, vinyl products have also become scarce."], "sentences": [{"text": "일본에서 비닐봉지가 부족해졌어요.", "translation": "Plastic bags have become scarce in Japan.", "vocab": [{"ko": "일본", "en": "Japan", "note": ""}, {"ko": "비닐봉지", "en": "plastic / vinyl bag", "note": ""}, {"ko": "부족하다", "en": "to be scarce / lacking", "note": ""}], "analysis": [{"type": "grammar", "label": "~에서 (action-location / source / starting point)", "exp": "action location marker. 일본 → 일본에서 (in Japan). Indicates the location where the state of scarcity occurs.", "example_in_sentence": "일본에서"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "subject particle marking the grammatical subject. 비닐봉지 → 비닐봉지가", "example_in_sentence": "비닐봉지가"}, {"type": "grammar", "label": "~아/어지다 (become)", "exp": "Shows a change: ''become ~''. 부족하다 → 부족해지다 → 부족해졌어요 (became scarce).", "example_in_sentence": "부족해졌어요"}]}, {"text": "슈퍼마켓과 빵집에서 비닐봉지를 구하기가 어려워졌어요.", "translation": "It has become hard to get plastic bags at supermarkets and bakeries.", "vocab": [{"ko": "슈퍼마켓", "en": "supermarket", "note": ""}, {"ko": "빵집", "en": "bakery", "note": ""}, {"ko": "비닐봉지", "en": "plastic / vinyl bag", "note": ""}, {"ko": "구하다", "en": "to find / obtain / seek", "note": ""}], "analysis": [{"type": "grammar", "label": "~과/와 (with — comitative / and — listing)", "exp": "listing particle (and). 슈퍼마켓과 빵집 (supermarkets and bakeries). Connects two noun phrases in a coordinate list.", "example_in_sentence": "슈퍼마켓과 빵집"}, {"type": "grammar", "label": "~에서 (location)", "exp": "Marks where an action happens. 슈퍼마켓과 빵집에서 (at supermarkets and bakeries).", "example_in_sentence": "빵집에서"}, {"type": "grammar", "label": "~을/를 (object marker)", "exp": "direct object particle. 비닐봉지 → 비닐봉지를 (seeking vinyl bags as direct object).", "example_in_sentence": "비닐봉지를"}, {"type": "grammar", "label": "~기 (nominalizer)", "exp": "verbal noun form. 구하다 → 구하기 (the act of finding, nominalised).", "example_in_sentence": "구하기"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "subject particle. 구하기 → 구하기가 (the action of finding as grammatical subject).", "example_in_sentence": "구하기가"}, {"type": "grammar", "label": "ㅂ 불규칙 (ㅂ irregular)", "exp": "어렵다 is ㅂ-irregular: ㅂ becomes 우 before 어. 어렵다 → 어려워지다 → 어려워졌어요 (became hard).", "example_in_sentence": "어려워졌어요"}, {"type": "grammar", "label": "~아/어지다 (become)", "exp": "Shows a change: ''become ~''. 어렵다 → 어려워졌어요 (became hard).", "example_in_sentence": "어려워졌어요"}]}, {"text": "음식 가게에서 쓰는 비닐 장갑도 부족해졌어요.", "translation": "Plastic gloves used in food shops have also become scarce.", "vocab": [{"ko": "음식", "en": "food", "note": ""}, {"ko": "가게", "en": "shop / store", "note": ""}, {"ko": "쓰다", "en": "to use / wear", "note": ""}, {"ko": "비닐", "en": "plastic / vinyl", "note": ""}], "analysis": [{"type": "grammar", "label": "~에서 (action-location / source / starting point)", "exp": "action location marker. 음식 가게에서 (in / at food shops). The location where gloves are used.", "example_in_sentence": "가게에서"}, {"type": "grammar", "label": "~는 (verb modifier)", "exp": "Lets a verb describe a noun. 쓰다 → 쓰는 장갑 (gloves that are used).", "example_in_sentence": "쓰는"}, {"type": "grammar", "label": "~도 (also / even)", "exp": "additive particle (also/too). 비닐 장갑도 (vinyl gloves too). Indicates that gloves, in addition to bags, have also become scarce.", "example_in_sentence": "장갑도"}, {"type": "grammar", "label": "~아/어지다 (become)", "exp": "Shows a change: ''become ~''. 부족하다 → 부족해졌어요 (became scarce).", "example_in_sentence": "부족해졌어요"}]}, {"text": "비닐봉지는 나프타로 만들어요.", "translation": "Plastic bags are made from naphtha.", "vocab": [{"ko": "비닐봉지", "en": "plastic / vinyl bag", "note": ""}, {"ko": "나프타", "en": "naphtha", "note": ""}, {"ko": "만들다", "en": "to make / manufacture", "note": ""}], "analysis": [{"type": "grammar", "label": "~은/는 (topic marker)", "exp": "topic particle. 비닐봉지는 (as for vinyl bags, topic of the sentence).", "example_in_sentence": "비닐봉지는"}, {"type": "grammar", "label": "~(으)로 (means / direction / transformation)", "exp": "material marker. 나프타로 (made FROM/OF naphtha as raw material).", "example_in_sentence": "나프타로"}, {"type": "grammar", "label": "~아/어요 (present polite)", "exp": "Polite present ending. 만들다 → 만들어요 (make).", "example_in_sentence": "만들어요"}]}, {"text": "중동은 일본의 가장 중요한 원유 공급지예요.", "translation": "The Middle East is Japan''s most important crude oil supply source.", "vocab": [{"ko": "중동", "en": "Middle East", "note": ""}, {"ko": "일본", "en": "Japan", "note": ""}, {"ko": "원유", "en": "crude oil", "note": ""}, {"ko": "공급지", "en": "supply source", "note": ""}], "analysis": [{"type": "grammar", "label": "~은/는 (topic marker)", "exp": "topic particle. 중동은 (as for the Middle East, the topic).", "example_in_sentence": "중동은"}, {"type": "grammar", "label": "~의 (possessive / relational)", "exp": "genitive / relational marker. 일본의 (of Japan / Japan''s).", "example_in_sentence": "일본의"}, {"type": "grammar", "label": "~ㄴ/은 (past verb / present adj modifier)", "exp": "adjective modifier form. 중요하다 → 중요한 (important, modifying 공급지).", "example_in_sentence": "중요한"}]}, {"text": "이란 전쟁 때문에 나프타가 부족해졌어요.", "translation": "Due to the Iran war, naphtha has become scarce.", "vocab": [{"ko": "이란", "en": "Iran", "note": ""}, {"ko": "전쟁", "en": "war", "note": ""}, {"ko": "나프타", "en": "naphtha", "note": ""}, {"ko": "부족하다", "en": "to be scarce / lacking", "note": ""}], "analysis": [{"type": "grammar", "label": "~ 때문에 (because of N)", "exp": "reason / cause marker. 이란 전쟁 때문에 (because of / due to the Iran war).", "example_in_sentence": "이란 전쟁 때문에"}, {"type": "grammar", "label": "~이/가 (subject marker)", "exp": "subject particle marking the grammatical subject. 나프타 → 나프타가 (naphtha as subject).", "example_in_sentence": "나프타가"}, {"type": "grammar", "label": "~아/어지다 (become)", "exp": "Shows a change: ''become ~''. 부족하다 → 부족해졌어요 (became scarce).", "example_in_sentence": "부족해졌어요"}]}, {"text": "그래서 비닐 제품도 부족해진 거예요.", "translation": "That is why plastic products have become scarce too.", "vocab": [{"ko": "비닐", "en": "plastic / vinyl", "note": ""}, {"ko": "제품", "en": "product", "note": ""}, {"ko": "부족하다", "en": "to be scarce / lacking", "note": ""}], "analysis": [{"type": "expression", "label": "그래서", "exp": "therefore / so. Causal connective linking the previous explanation (naphtha shortage due to war) to its consequence (vinyl product shortage).", "example_in_sentence": "그래서"}, {"type": "grammar", "label": "~도 (also / even)", "exp": "additive particle (also/too). 비닐 제품도 (vinyl products too). Indicates that vinyl products, in addition to naphtha, have become scarce.", "example_in_sentence": "제품도"}, {"type": "expression", "label": "~(으)ㄴ 거예요", "exp": "Explains a result: ''that''s why ~''. 부족해지다 → 부족해진 거예요 (that''s why they became scarce).", "example_in_sentence": "부족해진 거예요"}]}], "version": "s6"}', vocab = '[{"ko": "일본", "en": "Japan", "note": ""}, {"ko": "비닐봉지", "en": "plastic / vinyl bag", "note": ""}, {"ko": "부족하다", "en": "to be scarce / lacking", "note": ""}, {"ko": "슈퍼마켓", "en": "supermarket", "note": ""}, {"ko": "빵집", "en": "bakery", "note": ""}, {"ko": "구하다", "en": "to find / obtain / seek", "note": ""}, {"ko": "음식", "en": "food", "note": ""}, {"ko": "가게", "en": "shop / store", "note": ""}, {"ko": "쓰다", "en": "to use / wear", "note": ""}, {"ko": "비닐", "en": "plastic / vinyl", "note": ""}, {"ko": "나프타", "en": "naphtha", "note": ""}, {"ko": "만들다", "en": "to make / manufacture", "note": ""}, {"ko": "중동", "en": "Middle East", "note": ""}, {"ko": "원유", "en": "crude oil", "note": ""}, {"ko": "공급지", "en": "supply source", "note": ""}, {"ko": "이란", "en": "Iran", "note": ""}, {"ko": "전쟁", "en": "war", "note": ""}, {"ko": "제품", "en": "product", "note": ""}]', grammar = '{"patterns": [{"name": "~에서 (action-location / source / starting point)", "level": "Starter", "exp": "action location marker. 일본 → 일본에서 (in Japan). Indicates the location where the state of scarcity occurs.", "ex_ko": "일본에서 비닐봉지가 부족해졌어요.", "ex_en": "Plastic bags have become scarce in Japan."}, {"name": "~이/가 (subject marker)", "level": "Starter", "exp": "subject particle marking the grammatical subject. 나프타 → 나프타가 (naphtha as subject).", "ex_ko": "일본에서 비닐봉지가 부족해졌어요.", "ex_en": "Plastic bags have become scarce in Japan."}, {"name": "~아/어지다 (become)", "level": "Starter", "exp": "Shows a change: ''become ~''. 부족하다 → 부족해지다 → 부족해졌어요 (became scarce).", "ex_ko": "일본에서 비닐봉지가 부족해졌어요.", "ex_en": "Plastic bags have become scarce in Japan."}, {"name": "~과/와 (with — comitative / and — listing)", "level": "Starter", "exp": "listing particle (and). 슈퍼마켓과 빵집 (supermarkets and bakeries). Connects two noun phrases in a coordinate list.", "ex_ko": "슈퍼마켓과 빵집에서 비닐봉지를 구하기가 어려워졌어요.", "ex_en": "It has become hard to get plastic bags at supermarkets and bakeries."}, {"name": "~을/를 (object marker)", "level": "Starter", "exp": "direct object particle. 비닐봉지 → 비닐봉지를 (seeking vinyl bags as direct object).", "ex_ko": "슈퍼마켓과 빵집에서 비닐봉지를 구하기가 어려워졌어요.", "ex_en": "It has become hard to get plastic bags at supermarkets and bakeries."}, {"name": "~기 (nominalizer)", "level": "Starter", "exp": "verbal noun form. 구하다 → 구하기 (the act of finding, nominalised).", "ex_ko": "슈퍼마켓과 빵집에서 비닐봉지를 구하기가 어려워졌어요.", "ex_en": "It has become hard to get plastic bags at supermarkets and bakeries."}, {"name": "ㅂ 불규칙 (ㅂ irregular)", "level": "Starter", "exp": "어렵다 is ㅂ-irregular: ㅂ becomes 우 before 어. 어렵다 → 어려워지다 → 어려워졌어요 (became hard).", "ex_ko": "슈퍼마켓과 빵집에서 비닐봉지를 구하기가 어려워졌어요.", "ex_en": "It has become hard to get plastic bags at supermarkets and bakeries."}, {"name": "~는 (verb modifier)", "level": "Starter", "exp": "Lets a verb describe a noun. 쓰다 → 쓰는 장갑 (gloves that are used).", "ex_ko": "음식 가게에서 쓰는 비닐 장갑도 부족해졌어요.", "ex_en": "Plastic gloves used in food shops have also become scarce."}, {"name": "~도 (also / even)", "level": "Starter", "exp": "additive particle (also/too). 비닐 제품도 (vinyl products too). Indicates that vinyl products, in addition to naphtha, have become scarce.", "ex_ko": "음식 가게에서 쓰는 비닐 장갑도 부족해졌어요.", "ex_en": "Plastic gloves used in food shops have also become scarce."}, {"name": "~은/는 (topic marker)", "level": "Starter", "exp": "topic particle. 비닐봉지는 (as for vinyl bags, topic of the sentence).", "ex_ko": "비닐봉지는 나프타로 만들어요.", "ex_en": "Plastic bags are made from naphtha."}, {"name": "~(으)로 (means / direction / transformation)", "level": "Starter", "exp": "material marker. 나프타로 (made FROM/OF naphtha as raw material).", "ex_ko": "비닐봉지는 나프타로 만들어요.", "ex_en": "Plastic bags are made from naphtha."}, {"name": "~아/어요 (present polite)", "level": "Starter", "exp": "Polite present ending. 만들다 → 만들어요 (make).", "ex_ko": "비닐봉지는 나프타로 만들어요.", "ex_en": "Plastic bags are made from naphtha."}, {"name": "~의 (possessive / relational)", "level": "Starter", "exp": "genitive / relational marker. 일본의 (of Japan / Japan''s).", "ex_ko": "중동은 일본의 가장 중요한 원유 공급지예요.", "ex_en": "The Middle East is Japan''s most important crude oil supply source."}, {"name": "~ㄴ/은 (past verb / present adj modifier)", "level": "Starter", "exp": "adjective modifier form. 중요하다 → 중요한 (important, modifying 공급지).", "ex_ko": "중동은 일본의 가장 중요한 원유 공급지예요.", "ex_en": "The Middle East is Japan''s most important crude oil supply source."}, {"name": "~ 때문에 (because of N)", "level": "Starter", "exp": "reason / cause marker. 이란 전쟁 때문에 (because of / due to the Iran war).", "ex_ko": "이란 전쟁 때문에 나프타가 부족해졌어요.", "ex_en": "Due to the Iran war, naphtha has become scarce."}]}', updated_at = now() where article_id = 'mpzicoc322tz' and md5(translation) = '3998a9c31dab189b3f47151f4fb80712';
update public.article_cache set translation = '{"texts": ["An immigration court judge in Charlotte, North Carolina issued a deportation order against a teenager who was killed in 2024. The teenager''s name was Levi Mendes-Maldonado, and the deportation order was issued because he did not appear in court.", "The judge is said to have issued the deportation order because Levi did not appear in court. However, Levi had already died in 2024.", "In the respect that the deportation order was issued even after the fact of Levi''s death was communicated to the court, this case has become controversial. The situation is one in which a problem has been raised regarding whether it is appropriate to issue a deportation order to a dead person.", "This case can be seen as revealing serious problems related to U.S. immigration court procedures. It seems that what became a particular problem is the point that legal procedures proceeded as they were, even after the fact of death was confirmed."], "sentences": [{"text": "미국 노스캐롤라이나주 샬럿의 이민 법원 판사가 2024년에 살해된 한 청소년에게 추방 명령을 내렸습니다.", "translation": "An immigration court judge in Charlotte, North Carolina issued a deportation order against a teenager who was killed in 2024.", "vocab": [{"ko": "노스캐롤라이나주", "en": "North Carolina (state)", "note": ""}, {"ko": "이민 법원", "en": "immigration court", "note": ""}, {"ko": "살해되다", "en": "to be killed; to be murdered", "note": ""}, {"ko": "추방", "en": "deportation", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "Past formal-polite ending. 내리다 (put) → 내렸습니다 (issued). Marks completion in past with formal tone.", "example_in_sentence": "내렸습니다"}, {"type": "grammar", "label": "~에게/한테 (to person)", "exp": "Indirect object marker for animate beings. ''청소년에게'' = to the teenager.", "example_in_sentence": "청소년에게"}]}, {"text": "해당 청소년의 이름은 레비 멘데스-말도나도이며, 법원에 출석하지 않았다는 이유로 추방 명령이 내려진 것입니다.", "translation": "The teenager''s name was Levi Mendes-Maldonado, and the deportation order was issued because he did not appear in court.", "vocab": [{"ko": "해당", "en": "relevant / in question", "note": ""}, {"ko": "이유", "en": "reason / cause", "note": ""}, {"ko": "출석하다", "en": "to appear / to attend", "note": ""}], "analysis": [{"type": "grammar", "label": "~지 않다", "exp": "Long-form negation. 출석하다 → 출석하지 않다 = did not appear. More formal than short negation 안 출석했다.", "example_in_sentence": "출석하지 않았다"}, {"type": "grammar", "label": "~다는 이유로", "exp": "''On the grounds that ~''. 출석하지 않았다 → 출석하지 않았다는 이유로 (on the grounds that he did not appear).", "example_in_sentence": "출석하지 않았다는 이유로"}]}, {"text": "판사는 레비가 법원에 출석하지 않았기 때문에 추방 명령을 내렸다고 합니다.", "translation": "The judge is said to have issued the deportation order because Levi did not appear in court.", "vocab": [{"ko": "판사", "en": "judge", "note": ""}], "analysis": [{"type": "grammar", "label": "~지 않다", "exp": "Long-form negation. 출석하다 → 출석하지 않았다 = did not appear.", "example_in_sentence": "출석하지 않았다"}, {"type": "grammar", "label": "~기 때문에", "exp": "''Because''. 않다 → 않았기 때문에 (because he did not).", "example_in_sentence": "출석하지 않았기 때문에"}]}, {"text": "그러나 레비는 이미 2024년에 사망한 상태였습니다.", "translation": "However, Levi had already died in 2024.", "vocab": [{"ko": "사망하다", "en": "to die / to pass away", "note": "formal, often used in official/news contexts"}, {"ko": "상태", "en": "state / condition", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)ㄴ 상태였다", "exp": "''Was in a state of having ~ed''. 사망하다 → 사망한 상태였습니다 (had already died).", "example_in_sentence": "사망한 상태였습니다"}]}, {"text": "레비가 사망했다는 사실이 법원에 전달된 후에도 추방 명령이 내려졌다는 점에서 이 사건은 논란이 되고 있습니다.", "translation": "This case has become controversial because the deportation order was issued even after the court had been told that Levi had died.", "vocab": [{"ko": "사실", "en": "fact", "note": ""}, {"ko": "전달되다", "en": "to be delivered; to be passed on", "note": ""}, {"ko": "논란", "en": "controversy / dispute", "note": ""}], "analysis": [{"type": "grammar", "label": "~ㄴ/는다는 / ~라는 + N (the claim/fact/idea that)", "exp": "Attributive nominalizer. 사망했다는 사실 = the fact that (he) died; 내려졌다는 점 = the point that (the order) was issued.", "example_in_sentence": "사망했다는 사실"}, {"type": "grammar", "label": "~도 (also / even)", "exp": "Emphatic ''even''. 후에도 = even after; emphasizes surprise/contrast that action happened despite prior event.", "example_in_sentence": "후에도"}, {"type": "grammar", "label": "~고 있다 (continuous)", "exp": "Progressive aspect. 되다 → 되고 있습니다 = is becoming / is in the state of being controversial.", "example_in_sentence": "되고 있습니다"}, {"type": "grammar", "label": "~다는 점에서", "exp": "''In that ~ / because of the fact that ~''. 내려지다 → 내려졌다는 점에서 (in that the order was issued).", "example_in_sentence": "내려졌다는 점에서"}]}, {"text": "사망한 사람에게 추방 명령을 내리는 것이 적절한지를 두고 문제가 제기된 상황입니다.", "translation": "Questions have been raised over whether it is appropriate to issue a deportation order to a person who has died.", "vocab": [{"ko": "적절하다", "en": "to be appropriate / suitable", "note": ""}, {"ko": "제기되다", "en": "to be raised (an issue)", "note": ""}], "analysis": [{"type": "grammar", "label": "~에게/한테 (to person)", "exp": "Indirect object marker. ''사람에게'' = to the person.", "example_in_sentence": "사람에게"}, {"type": "grammar", "label": "~을/를 두고 (over / regarding)", "exp": "Topic-of-discussion marker. ''것을 두고'' = regarding/over the matter of issuing the order.", "example_in_sentence": "것을 두고"}, {"type": "expression", "label": "문제가 제기되다", "exp": "A problem / issue is raised / brought up. Passive construction marking that concerns have been voiced.", "example_in_sentence": "문제가 제기된"}]}, {"text": "이번 사건은 미국 이민 법원의 절차와 관련된 심각한 문제점을 드러낸 것으로 볼 수 있습니다.", "translation": "This case can be seen as revealing serious problems related to U.S. immigration court procedures.", "vocab": [{"ko": "절차", "en": "procedure / process", "note": ""}, {"ko": "심각하다", "en": "to be serious / grave", "note": ""}, {"ko": "문제점", "en": "problem / issue / flaw", "note": ""}, {"ko": "드러내다", "en": "to reveal / to expose", "note": ""}], "analysis": [{"type": "grammar", "label": "~과/와 관련된 (related to)", "exp": "Connection marker. ''절차와 관련된'' = related to / concerning the procedures.", "example_in_sentence": "절차와 관련된"}, {"type": "grammar", "label": "~(으)ㄴ 것으로 볼 수 있다", "exp": "''Can be seen as ~''. 드러내다 → 드러낸 것으로 볼 수 있습니다 (can be seen as having revealed).", "example_in_sentence": "드러낸 것으로 볼 수 있습니다"}]}, {"text": "사망 사실이 확인된 후에도 법적 절차가 그대로 진행되었다는 점이 특히 문제가 된 것 같습니다.", "translation": "What seems to have been especially problematic is that the legal process went ahead unchanged even after his death was confirmed.", "vocab": [{"ko": "확인되다", "en": "to be confirmed", "note": ""}, {"ko": "법적", "en": "legal", "note": ""}, {"ko": "진행되다", "en": "to proceed; to go ahead", "note": ""}], "analysis": [{"type": "grammar", "label": "~도 (also / even)", "exp": "Emphatic ''even''. ''후에도'' = even after; contrasts that procedures continued despite confirmation of death.", "example_in_sentence": "후에도"}, {"type": "grammar", "label": "~았/었다는 N", "exp": "Quotes a fact to describe a noun. 진행되다 → 진행되었다는 점 (the fact that it went ahead).", "example_in_sentence": "진행되었다는 점"}, {"type": "grammar", "label": "~(으)ㄴ 것 같다", "exp": "A guess about the past: ''it seems ~ed''. 되다 → 문제가 된 것 같습니다 (seems to have become a problem).", "example_in_sentence": "문제가 된 것 같습니다"}]}], "version": "s6"}', vocab = '[{"ko": "노스캐롤라이나주", "en": "North Carolina (state)", "note": ""}, {"ko": "이민 법원", "en": "immigration court", "note": ""}, {"ko": "살해되다", "en": "to be killed; to be murdered", "note": ""}, {"ko": "추방", "en": "deportation", "note": ""}, {"ko": "해당", "en": "relevant / in question", "note": ""}, {"ko": "이유", "en": "reason / cause", "note": ""}, {"ko": "출석하다", "en": "to appear / to attend", "note": ""}, {"ko": "판사", "en": "judge", "note": ""}, {"ko": "사망하다", "en": "to die / to pass away", "note": "formal, often used in official/news contexts"}, {"ko": "상태", "en": "state / condition", "note": ""}, {"ko": "사실", "en": "fact", "note": ""}, {"ko": "전달되다", "en": "to be delivered; to be passed on", "note": ""}, {"ko": "논란", "en": "controversy / dispute", "note": ""}, {"ko": "적절하다", "en": "to be appropriate / suitable", "note": ""}, {"ko": "제기되다", "en": "to be raised (an issue)", "note": ""}, {"ko": "절차", "en": "procedure / process", "note": ""}, {"ko": "심각하다", "en": "to be serious / grave", "note": ""}, {"ko": "문제점", "en": "problem / issue / flaw", "note": ""}, {"ko": "드러내다", "en": "to reveal / to expose", "note": ""}, {"ko": "확인되다", "en": "to be confirmed", "note": ""}, {"ko": "법적", "en": "legal", "note": ""}, {"ko": "진행되다", "en": "to proceed; to go ahead", "note": ""}]', grammar = '{"patterns": [{"name": "~았/었/였습니다 (past formal)", "level": "Intermediate", "exp": "Past formal-polite ending. 내리다 (put) → 내렸습니다 (issued). Marks completion in past with formal tone.", "ex_ko": "미국 노스캐롤라이나주 샬럿의 이민 법원 판사가 2024년에 살해된 한 청소년에게 추방 명령을 내렸습니다.", "ex_en": "An immigration court judge in Charlotte, North Carolina issued a deportation order against a teenager who was killed in 2024."}, {"name": "~에게/한테 (to person)", "level": "Intermediate", "exp": "Indirect object marker for animate beings. ''청소년에게'' = to the teenager.", "ex_ko": "미국 노스캐롤라이나주 샬럿의 이민 법원 판사가 2024년에 살해된 한 청소년에게 추방 명령을 내렸습니다.", "ex_en": "An immigration court judge in Charlotte, North Carolina issued a deportation order against a teenager who was killed in 2024."}, {"name": "~지 않다", "level": "Intermediate", "exp": "Long-form negation. 출석하다 → 출석하지 않다 = did not appear. More formal than short negation 안 출석했다.", "ex_ko": "해당 청소년의 이름은 레비 멘데스-말도나도이며, 법원에 출석하지 않았다는 이유로 추방 명령이 내려진 것입니다.", "ex_en": "The teenager''s name was Levi Mendes-Maldonado, and the deportation order was issued because he did not appear in court."}, {"name": "~다는 이유로", "level": "Intermediate", "exp": "''On the grounds that ~''. 출석하지 않았다 → 출석하지 않았다는 이유로 (on the grounds that he did not appear).", "ex_ko": "해당 청소년의 이름은 레비 멘데스-말도나도이며, 법원에 출석하지 않았다는 이유로 추방 명령이 내려진 것입니다.", "ex_en": "The teenager''s name was Levi Mendes-Maldonado, and the deportation order was issued because he did not appear in court."}, {"name": "~기 때문에", "level": "Intermediate", "exp": "''Because''. 않다 → 않았기 때문에 (because he did not).", "ex_ko": "판사는 레비가 법원에 출석하지 않았기 때문에 추방 명령을 내렸다고 합니다.", "ex_en": "The judge is said to have issued the deportation order because Levi did not appear in court."}, {"name": "~(으)ㄴ 상태였다", "level": "Intermediate", "exp": "''Was in a state of having ~ed''. 사망하다 → 사망한 상태였습니다 (had already died).", "ex_ko": "그러나 레비는 이미 2024년에 사망한 상태였습니다.", "ex_en": "However, Levi had already died in 2024."}, {"name": "~ㄴ/는다는 / ~라는 + N (the claim/fact/idea that)", "level": "Intermediate", "exp": "Attributive nominalizer. 사망했다는 사실 = the fact that (he) died; 내려졌다는 점 = the point that (the order) was issued.", "ex_ko": "레비가 사망했다는 사실이 법원에 전달된 후에도 추방 명령이 내려졌다는 점에서 이 사건은 논란이 되고 있습니다.", "ex_en": "This case has become controversial because the deportation order was issued even after the court had been told that Levi had died."}, {"name": "~도 (also / even)", "level": "Intermediate", "exp": "Emphatic ''even''. 후에도 = even after; emphasizes surprise/contrast that action happened despite prior event.", "ex_ko": "레비가 사망했다는 사실이 법원에 전달된 후에도 추방 명령이 내려졌다는 점에서 이 사건은 논란이 되고 있습니다.", "ex_en": "This case has become controversial because the deportation order was issued even after the court had been told that Levi had died."}, {"name": "~고 있다 (continuous)", "level": "Intermediate", "exp": "Progressive aspect. 되다 → 되고 있습니다 = is becoming / is in the state of being controversial.", "ex_ko": "레비가 사망했다는 사실이 법원에 전달된 후에도 추방 명령이 내려졌다는 점에서 이 사건은 논란이 되고 있습니다.", "ex_en": "This case has become controversial because the deportation order was issued even after the court had been told that Levi had died."}, {"name": "~다는 점에서", "level": "Intermediate", "exp": "''In that ~ / because of the fact that ~''. 내려지다 → 내려졌다는 점에서 (in that the order was issued).", "ex_ko": "레비가 사망했다는 사실이 법원에 전달된 후에도 추방 명령이 내려졌다는 점에서 이 사건은 논란이 되고 있습니다.", "ex_en": "This case has become controversial because the deportation order was issued even after the court had been told that Levi had died."}, {"name": "~을/를 두고 (over / regarding)", "level": "Intermediate", "exp": "Topic-of-discussion marker. ''것을 두고'' = regarding/over the matter of issuing the order.", "ex_ko": "사망한 사람에게 추방 명령을 내리는 것이 적절한지를 두고 문제가 제기된 상황입니다.", "ex_en": "Questions have been raised over whether it is appropriate to issue a deportation order to a person who has died."}, {"name": "~과/와 관련된 (related to)", "level": "Intermediate", "exp": "Connection marker. ''절차와 관련된'' = related to / concerning the procedures.", "ex_ko": "이번 사건은 미국 이민 법원의 절차와 관련된 심각한 문제점을 드러낸 것으로 볼 수 있습니다.", "ex_en": "This case can be seen as revealing serious problems related to U.S. immigration court procedures."}, {"name": "~(으)ㄴ 것으로 볼 수 있다", "level": "Intermediate", "exp": "''Can be seen as ~''. 드러내다 → 드러낸 것으로 볼 수 있습니다 (can be seen as having revealed).", "ex_ko": "이번 사건은 미국 이민 법원의 절차와 관련된 심각한 문제점을 드러낸 것으로 볼 수 있습니다.", "ex_en": "This case can be seen as revealing serious problems related to U.S. immigration court procedures."}, {"name": "~았/었다는 N", "level": "Intermediate", "exp": "Quotes a fact to describe a noun. 진행되다 → 진행되었다는 점 (the fact that it went ahead).", "ex_ko": "사망 사실이 확인된 후에도 법적 절차가 그대로 진행되었다는 점이 특히 문제가 된 것 같습니다.", "ex_en": "What seems to have been especially problematic is that the legal process went ahead unchanged even after his death was confirmed."}, {"name": "~(으)ㄴ 것 같다", "level": "Intermediate", "exp": "A guess about the past: ''it seems ~ed''. 되다 → 문제가 된 것 같습니다 (seems to have become a problem).", "ex_ko": "사망 사실이 확인된 후에도 법적 절차가 그대로 진행되었다는 점이 특히 문제가 된 것 같습니다.", "ex_en": "What seems to have been especially problematic is that the legal process went ahead unchanged even after his death was confirmed."}]}', updated_at = now() where article_id = 'mpzie39b51rc' and md5(translation) = '428e974974889343f422d911d02b286a';
update public.article_cache set translation = '{"texts": ["Samsung Electronics, SK Hynix, and Micron have been sued in the United States on suspicion that the three companies engaged in price fixing for memory semiconductors. This lawsuit was filed in a U.S. court, and all three companies are industry leaders in the global memory semiconductor market.", "The plaintiff argues that the three companies maintained artificially high memory prices while agreeing with each other. The core claim of the lawsuit is that as a result, consumers and companies paid higher costs than normal prices.", "This lawsuit was filed on the basis of allegations of antitrust law violations. If the collusion is confirmed as fact, the three companies may have to pay substantial damages.", "Samsung Electronics, SK Hynix, and Micron account for most of the global DRAM market, and on top of that, this lawsuit is expected to have significant impact. Attention is being paid to how the legal dispute surrounding allegations of memory price fixing will unfold going forward."], "sentences": [{"text": "삼성전자, SK하이닉스, 마이크론 세 회사가 메모리 반도체 가격을 담합했다는 혐의로 미국에서 소송을 당했습니다.", "translation": "Samsung Electronics, SK Hynix, and Micron have been sued in the United States on suspicion that the three companies engaged in price fixing for memory semiconductors.", "vocab": [{"ko": "반도체", "en": "semiconductor", "note": ""}, {"ko": "담합하다", "en": "to engage in collusion/price fixing", "note": ""}, {"ko": "혐의", "en": "suspicion; allegation", "note": ""}, {"ko": "소송", "en": "lawsuit; litigation", "note": ""}], "analysis": [{"type": "grammar", "label": "~았/었다는 N", "exp": "Quotes a claim to describe a noun. 담합하다 → 담합했다는 혐의 (the allegation that they fixed prices).", "example_in_sentence": "담합했다는 혐의"}, {"type": "grammar", "label": "~에서 (action-location / source)", "exp": "Action-location marker: marks where a dynamic action takes place. 미국에서 소송을 당하다 = ''be sued in the United States'' (action occurs in the US).", "example_in_sentence": "미국에서 소송을 당했습니다"}, {"type": "grammar", "label": "~(으)로 (grounds)", "exp": "Marks the grounds or reason for something. 혐의로 (on charges of).", "example_in_sentence": "혐의로"}, {"type": "grammar", "label": "소송을 당하다", "exp": "''Be sued''. 당하다 marks suffering an action done to you: 소송을 당했습니다 (were sued).", "example_in_sentence": "소송을 당했습니다"}]}, {"text": "이 소송은 미국 법원에 제기되었으며, 세 회사 모두 글로벌 메모리 반도체 시장을 주도하는 기업들입니다.", "translation": "This lawsuit was filed in a U.S. court, and all three companies are industry leaders in the global memory semiconductor market.", "vocab": [{"ko": "법원", "en": "court", "note": ""}, {"ko": "제기되다", "en": "to be filed; to be raised", "note": ""}, {"ko": "글로벌", "en": "global", "note": ""}, {"ko": "주도하다", "en": "to lead; to dominate", "note": ""}], "analysis": [{"type": "grammar", "label": "~에 (location; target of action)", "exp": "Target/locative particle. Marks where the lawsuit is filed: 법원에 제기 = ''filed in/to the court''.", "example_in_sentence": "미국 법원에 제기되었으며"}, {"type": "grammar", "label": "~(으)며", "exp": "Formal written connector meaning ''and''. 제기되다 → 제기되었으며 (was filed, and).", "example_in_sentence": "제기되었으며"}, {"type": "expression", "label": "~을/를 주도하다", "exp": "Collocation: ''to lead / dominate (a market)''. Market leadership marker.", "example_in_sentence": "글로벌 메모리 반도체 시장을 주도하는 기업들"}]}, {"text": "원고 측은 세 회사가 서로 합의하면서 메모리 가격을 인위적으로 높게 유지했다고 주장합니다.", "translation": "The plaintiffs claim that the three companies colluded to keep memory prices artificially high.", "vocab": [{"ko": "원고", "en": "plaintiff", "note": ""}, {"ko": "측", "en": "side; party", "note": ""}, {"ko": "합의하다", "en": "to agree; to reach an agreement", "note": ""}, {"ko": "인위적", "en": "artificial; artificially contrived", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)면서 (while / simultaneous action)", "exp": "Simultaneous-action marker. Two actions happen at once by the same subject: ''합의하다'' (agree) and ''유지하다'' (maintain prices) occur together.", "example_in_sentence": "서로 합의하면서 메모리 가격을 인위적으로 높게 유지했다"}, {"type": "grammar", "label": "~게 (adverbializer)", "exp": "Forms adverb from adjective. 높다 (high) → 높게 (highly). Here: 가격을 높게 유지 = ''maintain prices high''.", "example_in_sentence": "높게 유지했다"}, {"type": "grammar", "label": "~적으로", "exp": "Adverb form of ~적 words: ''in a ~ way''. 인위적 (artificial) → 인위적으로 (artificially).", "example_in_sentence": "인위적으로"}, {"type": "grammar", "label": "~다고 주장하다", "exp": "Reports a claim: ''claim that ~''. 유지했다 → 유지했다고 주장합니다 (claim that they kept).", "example_in_sentence": "높게 유지했다고 주장합니다"}]}, {"text": "이로 인해 소비자와 기업들이 정상 가격보다 더 높은 비용을 지불했다는 것이 소송의 핵심 내용입니다.", "translation": "The core claim of the lawsuit is that as a result, consumers and companies paid higher costs than normal prices.", "vocab": [{"ko": "소비자", "en": "consumer", "note": ""}, {"ko": "기업", "en": "company; enterprise", "note": ""}, {"ko": "정상", "en": "normal; standard", "note": ""}, {"ko": "가격", "en": "price", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)로 인해/인한 (due to; causation)", "exp": "Causation marker. 이 (this collusion) + 로 인해 = ''due to / as a result of''. Links cause (price fixing) to effect (overpayment).", "example_in_sentence": "이로 인해"}, {"type": "grammar", "label": "~과/와 (and; listing)", "exp": "Formal listing conjunction. Connects two noun phrases: 소비자 (consumers) and 기업들 (companies) as joint subjects.", "example_in_sentence": "소비자와 기업들이"}, {"type": "grammar", "label": "~보다 (comparison: than)", "exp": "Comparative particle. 정상 가격보다 = ''than normal prices''. Marks the reference point for comparison.", "example_in_sentence": "정상 가격보다 더 높은 비용"}, {"type": "grammar", "label": "~았/었다는 것", "exp": "Turns a reported statement into a noun: ''the fact that ~''. 지불했다 → 지불했다는 것 (that they paid).", "example_in_sentence": "지불했다는 것이"}]}, {"text": "이번 소송은 반독점법 위반 혐의를 토대로 제기되었습니다.", "translation": "This lawsuit was filed on the basis of allegations of antitrust law violations.", "vocab": [{"ko": "반독점법", "en": "antitrust law", "note": ""}, {"ko": "위반", "en": "violation", "note": ""}], "analysis": [{"type": "grammar", "label": "~을/를 토대로 (on the basis of)", "exp": "Foundation/grounds marker. 혐의를 토대로 = ''on the basis of / grounded in allegations''. Indicates what the lawsuit is built upon.", "example_in_sentence": "반독점법 위반 혐의를 토대로"}, {"type": "grammar", "label": "~았/었/였습니다 (past formal)", "exp": "Past tense formal-polite. 제기하다 (passive: 되다) + 었습니다 = ''was filed''.", "example_in_sentence": "제기되었습니다"}]}, {"text": "담합이 사실로 확인될 경우, 세 회사는 상당한 규모의 손해배상을 해야 할 수도 있습니다.", "translation": "If the collusion is confirmed as fact, the three companies may have to pay substantial damages.", "vocab": [{"ko": "사실", "en": "fact; truth", "note": ""}, {"ko": "확인되다", "en": "to be confirmed", "note": ""}, {"ko": "경우", "en": "case; situation", "note": ""}, {"ko": "상당하다", "en": "to be considerable; substantial", "note": ""}], "analysis": [{"type": "grammar", "label": "~(으)로 (transformation / manner)", "exp": "Category/transformation marker. 사실로 확인 = ''confirmed as fact'' (neutral state: 담합 → 사실). Indicates the state into which something changes.", "example_in_sentence": "사실로 확인될 경우"}, {"type": "grammar", "label": "~(으)ㄹ 경우", "exp": "''In case / if ~''. 확인되다 → 확인될 경우 (if it is confirmed).", "example_in_sentence": "확인될 경우"}, {"type": "grammar", "label": "~아/어야 하다 (must; obligation)", "exp": "Obligation marker. 해야 하다 = ''must / have to''. Here: 손해배상을 해야 = ''must pay damages''.", "example_in_sentence": "손해배상을 해야 할 수도"}, {"type": "grammar", "label": "~(으)ㄹ 수도 있다", "exp": "''May / might''. 해야 하다 → 해야 할 수도 있습니다 (may have to).", "example_in_sentence": "해야 할 수도 있습니다"}]}, {"text": "삼성전자, SK하이닉스, 마이크론은 전 세계 D램 시장의 대부분을 차지하고 있는 데다가, 이번 소송의 파급력도 클 것으로 보입니다.", "translation": "Samsung Electronics, SK Hynix, and Micron account for most of the global DRAM market, and on top of that, this lawsuit is expected to have significant impact.", "vocab": [{"ko": "전 세계", "en": "the world; global", "note": ""}, {"ko": "D램", "en": "DRAM (dynamic random-access memory)", "note": ""}, {"ko": "시장", "en": "market", "note": ""}, {"ko": "대부분", "en": "the majority; most", "note": ""}], "analysis": [{"type": "grammar", "label": "~을/를 차지하다 (account for; occupy)", "exp": "Market/position-share marker. 대부분을 차지하다 = ''account for / occupy the majority''. Indicates what proportion the three companies control.", "example_in_sentence": "전 세계 D램 시장의 대부분을 차지하고"}, {"type": "grammar", "label": "~고 있다 (continuous aspect)", "exp": "Progressive / ongoing state. 차지하고 있다 = ''are accounting for / currently hold''. Implies continuous present status.", "example_in_sentence": "차지하고 있는 데다가"}, {"type": "grammar", "label": "~ㄴ/는 데다(가) (in addition; on top of)", "exp": "Additive clause marker. Links two facts: ''they hold most of the market'' AND ''on top of that, the lawsuit has big impact''. Means ''moreover / what''s more''.", "example_in_sentence": "차지하고 있는 데다가"}, {"type": "grammar", "label": "~도 (also / even; emphatic)", "exp": "Emphatic particle. 파급력도 크다 = ''the impact is also / even large''. Adds emphasis that impact too will be considerable.", "example_in_sentence": "파급력도 클"}, {"type": "grammar", "label": "~(으)ㄹ 것으로 보이다", "exp": "News phrase: ''seems likely / is expected to ~''. 크다 → 클 것으로 보입니다 (seems likely to be large).", "example_in_sentence": "클 것으로 보입니다"}]}, {"text": "메모리 가격 담합 혐의를 둘러싼 법적 공방이 앞으로 어떻게 전개될지 주목됩니다.", "translation": "Attention is being paid to how the legal dispute surrounding allegations of memory price fixing will unfold going forward.", "vocab": [{"ko": "담합", "en": "collusion; price fixing", "note": ""}, {"ko": "혐의", "en": "suspicion; allegation", "note": ""}, {"ko": "둘러싸다", "en": "to surround; to center on", "note": "past participle of 둘러싸다"}, {"ko": "법적", "en": "legal", "note": ""}], "analysis": [{"type": "grammar", "label": "~을/를 둘러싼 (surrounding; over)", "exp": "Topic-of-dispute marker. ''혐의를 둘러싼'' = ''surrounding the allegation of''. Marks the subject of contention or focus.", "example_in_sentence": "메모리 가격 담합 혐의를 둘러싼"}, {"type": "grammar", "label": "~되다 (passive)", "exp": "주목하다 (pay attention) → 주목되다 (draw attention). 주목됩니다 = it is drawing attention.", "example_in_sentence": "주목됩니다"}, {"type": "expression", "label": "~(으)ㄹ지", "exp": "Embeds an uncertain question: ''how ~ will''. 전개되다 → 어떻게 전개될지 (how it will unfold).", "example_in_sentence": "어떻게 전개될지"}]}], "version": "s6"}', vocab = '[{"ko": "반도체", "en": "semiconductor", "note": ""}, {"ko": "담합하다", "en": "to engage in collusion/price fixing", "note": ""}, {"ko": "혐의", "en": "suspicion; allegation", "note": ""}, {"ko": "소송", "en": "lawsuit; litigation", "note": ""}, {"ko": "법원", "en": "court", "note": ""}, {"ko": "제기되다", "en": "to be filed; to be raised", "note": ""}, {"ko": "글로벌", "en": "global", "note": ""}, {"ko": "주도하다", "en": "to lead; to dominate", "note": ""}, {"ko": "원고", "en": "plaintiff", "note": ""}, {"ko": "측", "en": "side; party", "note": ""}, {"ko": "합의하다", "en": "to agree; to reach an agreement", "note": ""}, {"ko": "인위적", "en": "artificial; artificially contrived", "note": ""}, {"ko": "소비자", "en": "consumer", "note": ""}, {"ko": "기업", "en": "company; enterprise", "note": ""}, {"ko": "정상", "en": "normal; standard", "note": ""}, {"ko": "가격", "en": "price", "note": ""}, {"ko": "반독점법", "en": "antitrust law", "note": ""}, {"ko": "위반", "en": "violation", "note": ""}, {"ko": "사실", "en": "fact; truth", "note": ""}, {"ko": "확인되다", "en": "to be confirmed", "note": ""}, {"ko": "경우", "en": "case; situation", "note": ""}, {"ko": "상당하다", "en": "to be considerable; substantial", "note": ""}, {"ko": "전 세계", "en": "the world; global", "note": ""}, {"ko": "D램", "en": "DRAM (dynamic random-access memory)", "note": ""}, {"ko": "시장", "en": "market", "note": ""}, {"ko": "대부분", "en": "the majority; most", "note": ""}, {"ko": "담합", "en": "collusion; price fixing", "note": ""}, {"ko": "둘러싸다", "en": "to surround; to center on", "note": "past participle of 둘러싸다"}, {"ko": "법적", "en": "legal", "note": ""}]', gr